  }, [history, customSongs, draft, learningList, isLoading]);

  useEffect(() => {
    if (!isReadyForCloudSync || !user || isOffline) return;

    setSyncStatus('syncing');
    if (syncTimeoutRef.current) window.clearTimeout(syncTimeoutRef.current);

    syncTimeoutRef.current = window.setTimeout(async () => {
      try {
        const { error } = await supabase.from('user_data').upsert({ 
          user_id: user.id, 
          json_data: { history, customSongs, learningList },
          updated_at: new Date().toISOString()
        }, { onConflict: 'user_id' });

        if (error) throw error;
        setSyncStatus('synced');
      } catch (e) {
        console.error("Falha no Auto-Sync Cloud:", e);
        setSyncStatus('local');
      }
    }, 3000);

    return () => {
      if (syncTimeoutRef.current) window.clearTimeout(syncTimeoutRef.current);
    };
  }, [history, customSongs, learningList, user, isOffline, isReadyForCloudSync]);

  const handleManualUpload = async () => {
    if (!user || isOffline) return;
    setIsCloudActionLoading(true);
    try {
      const { error } = await supabase.from('user_data').upsert({
        user_id: user.id,
        json_data: { history, customSongs, learningList },
        updated_at: new Date().toISOString()
      }, { onConflict: 'user_id' });
      if (error) throw error;
      setSyncStatus('synced');
      alert("Dados enviados para a nuvem com sucesso!");
    } catch (e) {
      alert("Erro ao sincronizar dados.");
    } finally {
      setIsCloudActionLoading(false);
    }
  };

  const handleManualDownload = async () => {
    if (!user || isOffline) return;
    if (!window.confirm("Isso substituirá seus dados locais pela versão da nuvem. Continuar?")) return;
    setIsCloudActionLoading(true);
    try {
      const { data } = await supabase.from('user_data').select('json_data').eq('user_id', user.id).maybeSingle();
      if (data?.json_data) {
        setHistory(data.json_data.history || []);
        setCustomSongs(data.json_data.customSongs || []);
        setLearningList(data.json_data.learningList || []);
        alert("Dados recuperados da nuvem!");
      } else {
        alert("Nenhum dado encontrado na nuvem.");
      }
    } catch (e) {
      alert("Erro ao baixar dados.");
    } finally {
      setIsCloudActionLoading(false);
    }
  };

  const fullSongList = useMemo(() => {
    return [...new Set([...INITIAL_PRAISE_LIST, ...customSongs])].sort((a, b) => a.localeCompare(b));
  }, [customSongs]);

  const songStats = useMemo(() => {
    const stats: Record<string, SongStats> = {};
    history.forEach(record => {
      record.songs.forEach(song => {
        if (!stats[song]) stats[song] = { song, count: 0, lastDate: null, history: [] };
        stats[song].count++;
        stats[song].history.push(record.date);
      });
    });
    Object.keys(stats).forEach(s => {
      stats[s].history.sort((a, b) => b.localeCompare(a));
      stats[s].lastDate = stats[s].history[0];
    });
    return stats;
  }, [history]);

  const saveRecord = (data: Omit<ServiceRecord, 'id'>) => {
    if (editingId) {
      setHistory(prev => prev.map(r => r.id === editingId ? { ...data, id: editingId } : r));
      setEditingId(null);
    } else {
      setHistory(prev => [{ ...data, id: crypto.randomUUID() }, ...prev]);
    }
    setDraft({ date: getTodayDate(), description: '', songs: [], roles: { ...emptyRoles } });
  };

  const menuItems = [
    { id: 'new', icon: 'add_circle', label: 'Novo Culto' },
    { id: 'history', icon: 'history', label: 'Histórico' },
    { id: 'learning', icon: 'school', label: 'Aprendizado' },
    { id: 'workers', icon: 'emoji_events', label: 'Ranking Obreiros' },
    { id: 'suggestions', icon: 'assignment_ind', label: 'Escala / Sugestão' },
    { id: 'praise-ranking', icon: 'trending_up', label: 'Ranking Hinos' },
    { id: 'unplayed', icon: 'assignment_late', label: 'Hinos Restantes' },
    { id: 'settings', icon: 'settings', label: 'Backup / Sistema' },
  ] as const;

  const handleTabChange = (id: typeof activeTab) => {
    setActiveTab(id);
    setIsMobileMenuOpen(false);
    window.scrollTo(0,0);
  };

  const AppBrand = () => (
    <div className="flex items-center gap-5">
      <div className="w-16 h-16 bg-white rounded-2xl shadow-xl flex items-center justify-center p-2.5">
        <img src="https://cdn-icons-png.flaticon.com/512/1672/1672225.png" alt="Logo" className="w-full h-full object-contain" />
      </div>
      <div className="flex flex-col">
        <div className="flex items-center gap-2">
           <span className={`material-icons text-[14px] ${syncStatus === 'synced' ? 'text-emerald-400' : syncStatus === 'syncing' ? 'text-amber-400 animate-spin' : 'text-white/20'}`}>
             {syncStatus === 'synced' ? 'cloud_done' : syncStatus === 'syncing' ? 'sync' : 'cloud_off'}
           </span>
           <span className="text-white/60 font-black text-[10px] tracking-[0.2em] uppercase">
             {syncStatus === 'synced' ? 'Nuvem OK' : syncStatus === 'syncing' ? 'Salvando...' : 'Local'}
           </span>
        </div>
        <h1 className="text-white font-black text-xl tracking-tighter leading-tight uppercase whitespace-nowrap">Santo Antônio II</h1>
        <div className="mt-1 bg-white/10 self-start px-3 py-1 rounded-full flex items-center gap-2">
           <span className="material-icons text-amber-400 text-xs">analytics</span>
           <span className="text-white font-black text-[10px] uppercase">{history.length} Cultos</span>
        </div>
      </div>
    </div>
  );

  const UserProfile = () => {
    if (!user) {
      return (
        <div className="px-10 py-8 border-b border-white/5 animate-fadeIn">
          <button 
            onClick={() => setShowLoginModal(true)}
            className="w-full py-5 bg-amber-400 text-[#1a1c3d] rounded-2xl font-black text-[11px] uppercase tracking-widest flex items-center justify-center gap-3 shadow-lg active:scale-95 transition-all"
          >
            <span className="material-icons text-lg">cloud_sync</span>
            Entrar / Sincronizar
          </button>
        </div>
      );
    }
    return (
      <div className="px-10 py-8 border-b border-white/5 space-y-6 bg-white/5 animate-fadeIn">
        <div className="flex items-center gap-4">
          <div className="w-12 h-12 bg-indigo-50 rounded-2xl flex items-center justify-center overflow-hidden border border-white/10 shrink-0">
            <span className="material-icons text-[#1a1c3d] text-2xl">person</span>
          </div>
          <div className="flex flex-col min-w-0 flex-1">
            <span className="text-white font-black text-xs uppercase truncate leading-tight">{user.email?.split('@')[0]}</span>
            <div className="flex items-center gap-1.5 mt-0.5">
              <span className={`w-1.5 h-1.5 rounded-full ${isOffline ? 'bg-rose-500' : 'bg-emerald-400 animate-pulse'}`}></span>
              <span className="text-white/30 font-bold text-[8px] uppercase tracking-widest">{isOffline ? 'Offline' : 'Conectado'}</span>
            </div>
          </div>
          <button 
            onClick={() => supabase.auth.signOut()}
            className="w-10 h-10 bg-rose-500/10 rounded-xl flex items-center justify-center text-rose-400 hover:bg-rose-500/20 transition-all"
            title="Sair"
          >
            <span className="material-icons text-sm">logout</span>
          </button>
        </div>

        <div className="grid grid-cols-2 gap-3">
          <button 
            disabled={isCloudActionLoading || isOffline}
            onClick={handleManualUpload}
            className="flex-1 bg-indigo-500 hover:bg-indigo-600 text-white py-3 rounded-xl flex flex-col items-center justify-center gap-1 transition-all active:scale-95 shadow-lg disabled:opacity-50"
          >
            <span className={`material-icons text-sm ${isCloudActionLoading ? 'animate-spin' : ''}`}>cloud_upload</span>
            <span className="text-[7px] font-black uppercase tracking-widest">Sincronizar</span>
          </button>
          <button 
            disabled={isCloudActionLoading || isOffline}
            onClick={handleManualDownload}
            className="flex-1 bg-amber-400 hover:bg-amber-500 text-[#1a1c3d] py-3 rounded-xl flex flex-col items-center justify-center gap-1 transition-all active:scale-95 shadow-lg disabled:opacity-50"
          >
            <span className={`material-icons text-sm ${isCloudActionLoading ? 'animate-spin' : ''}`}>cloud_download</span>
            <span className="text-[7px] font-black uppercase tracking-widest">Recuperar</span>
          </button>
        </div>
      </div>
    );
  };

  if (isLoading) return <div className="min-h-screen bg-[#1a1c3d] flex flex-col items-center justify-center text-white p-10"><img src="https://cdn-icons-png.flaticon.com/512/1672/1672225.png" className="w-20 h-20 animate-bounce mb-6" /><p className="font-black tracking-widest text-sm animate-pulse">CARREGANDO SISTEMA...</p></div>;

  return (
    <div className="min-h-screen bg-slate-100 flex flex-col md:flex-row">
      <aside className="hidden md:flex w-96 bg-[#1a1c3d] flex-col sticky top-0 h-screen shadow-2xl z-[150]">
        <div className="p-12 border-b border-white/5">
          <AppBrand />
        </div>

        <UserProfile />

        <nav className="flex-1 py-4 overflow-y-auto custom-scrollbar">
          {menuItems.map(item => (
            <button 
              key={item.id}
              onClick={() => handleTabChange(item.id)}
              className={`w-full flex items-center gap-6 px-12 py-6 transition-all duration-300 ${activeTab === item.id ? 'bg-amber-400 text-[#1a1c3d] font-black' : 'text-white/40 hover:text-white hover:bg-white/5'}`}
            >
              <span className="material-icons text-2xl">{item.icon}</span>
              <span className="text-sm uppercase font-black tracking-widest">{item.label}</span>
            </button>
          ))}
        </nav>
      </aside>

      <header className="md:hidden bg-[#1a1c3d] text-white p-6 sticky top-0 z-[200] flex justify-between items-center shadow-2xl rounded-b-[2rem]">
        <AppBrand />
        <button onClick={() => setIsMobileMenuOpen(true)} className="p-4 bg-white/10 rounded-2xl active:scale-90 transition-transform">
          <span className="material-icons text-3xl">menu</span>
        </button>
      </header>

      {isMobileMenuOpen && (
        <div className="fixed inset-0 z-[300] md:hidden">
          <div className="absolute inset-0 bg-[#1a1c3d]/90 backdrop-blur-lg" onClick={() => setIsMobileMenuOpen(false)}></div>
          <div className="absolute top-0 right-0 bottom-0 w-[85%] bg-[#1a1c3d] shadow-2xl flex flex-col animate-slideInRight border-l border-white/5">
            <div className="p-10 flex justify-between items-center border-b border-white/5">
              <span className="text-white/40 font-black text-xs tracking-widest uppercase">Navegação Principal</span>
              <button onClick={() => setIsMobileMenuOpen(false)} className="w-12 h-12 bg-white/5 rounded-full flex items-center justify-center text-white/40"><span className="material-icons">close</span></button>
            </div>

            <UserProfile />

            <nav className="flex-1 py-4 overflow-y-auto">
              {menuItems.map(item => (
                <button 
                  key={item.id}
                  onClick={() => handleTabChange(item.id)}
                  className={`w-full flex items-center gap-8 px-10 py-7 border-b border-white/5 ${activeTab === item.id ? 'text-amber-400 bg-white/5 font-black' : 'text-white/60'}`}
                >
                  <span className="material-icons text-3xl">{item.icon}</span>
                  <span className="text-base font-black uppercase tracking-widest">{item.label}</span>
                </button>
              ))}
            </nav>
          </div>
        </div>
      )}

      {showLoginModal && (
        <div className="fixed inset-0 z-[9999] flex items-center justify-center p-6">
          <div className="absolute inset-0 bg-[#1a1c3d]/95 backdrop-blur-xl animate-fadeIn" onClick={() => setShowLoginModal(false)} />
          <div className="relative bg-white/5 border border-white/10 rounded-[3rem] p-10 w-full max-w-sm shadow-2xl animate-scaleUp">
            <div className="flex flex-col items-center text-center mb-8">
              <div className="w-20 h-20 bg-amber-400 rounded-3xl flex items-center justify-center mb-6 shadow-xl shadow-amber-400/20">
                <span className="material-icons text-4xl text-[#1a1c3d]">cloud_sync</span>
              </div>
              <h2 className="text-white font-black text-2xl uppercase tracking-tighter">Sincronizar</h2>
              <p className="text-white/40 font-bold text-[10px] uppercase tracking-widest mt-2 leading-relaxed">Acesse sua conta para manter seus dados seguros em qualquer lugar.</p>
            </div>
            <AuthForm onSuccess={() => setShowLoginModal(false)} />
            <button 
              onClick={() => setShowLoginModal(false)}
              className="w-full mt-6 py-4 text-white/20 font-black text-[10px] uppercase tracking-widest hover:text-white transition-all"
            >
              FECHAR
            </button>
          </div>
        </div>
      )}

      <main className="flex-1 min-w-0">
        {isOffline && <div className="bg-amber-500 text-white text-[10px] font-black uppercase py-2.5 text-center sticky top-[92px] md:top-0 z-[190] shadow-lg">Você está operando offline.</div>}

        <div className="px-4 pt-14 pb-20 md:p-16 animate-fadeIn max-w-6xl mx-auto">
          {activeTab === 'new' && <ServiceForm onSave={saveRecord} songStats={songStats} fullSongList={fullSongList} onRegisterNewSong={s => setCustomSongs(prev => [...prev, s])} draft={draft} setDraft={setDraft} editingId={editingId} onCancelEdit={() => setEditingId(null)} />}
          {activeTab === 'history' && <HistoryList history={history} onDelete={id => setHistory(prev => prev.filter(r => r.id !== id))} onEdit={r => { setEditingId(r.id); setDraft({ ...r }); setActiveTab('new'); }} onClearAll={() => {}} />}
          {activeTab === 'learning' && <PraiseLearningList fullSongList={fullSongList} learningList={learningList} setLearningList={setLearningList} />}
          {activeTab === 'workers' && <WorkerRanking history={history} />}
          {activeTab === 'suggestions' && <WorkerStats history={history} />}
          {activeTab === 'praise-ranking' && <RankingList songStats={songStats} />}
          {activeTab === 'unplayed' && <UnplayedList fullSongList={INITIAL_PRAISE_LIST} history={history} />}
          {activeTab === 'settings' && <BackupRestore history={history} customSongs={customSongs} learningList={learningList} onRestore={(h, c, l) => { setHistory(h); setCustomSongs(c); setLearningList(l || []); }} />}
        </div>
      </main>
    </div>
  );
};

export default App;

import React, { useRef } from 'react';
import { ServiceRecord, PraiseLearningItem } from '../types';

interface Props {
  history: ServiceRecord[];
  customSongs: string[];
  learningList: PraiseLearningItem[];
  onRestore: (history: ServiceRecord[], customSongs: string[], learningList: PraiseLearningItem[]) => void;
}

const BackupRestore: React.FC<Props> = ({ history, customSongs, learningList, onRestore }) => {
  const fileInputRef = useRef<HTMLInputElement>(null);

  const handleBackup = () => {
    const dataStr = JSON.stringify({ history, customSongs, learningList }, null, 2);
    const blob = new Blob([dataStr], { type: 'application/json' });
    const url = URL.createObjectURL(blob);
    const link = document.createElement('a');
    link.href = url;
    link.download = `backup_igreja_${new Date().toISOString().split('T')[0]}.json`;
    link.click();
  };

  const handleFileChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;
    const reader = new FileReader();
    reader.onload = (event) => {
      try {
        const json = JSON.parse(event.target?.result as string);
        if (json && Array.isArray(json.history)) {
          if (window.confirm("Isso substituirá seus dados atuais pelos dados do arquivo. Continuar?")) {
            onRestore(json.history, json.customSongs || [], json.learningList || []);
          }
        }
      } catch (err) { alert("Arquivo inválido."); }
    };
    reader.readAsText(file);
  };

  return (
    <div className="space-y-10 animate-fadeIn max-w-4xl mx-auto pb-10">
      <div className="px-2">
        <h2 className="text-2xl font-black text-slate-800 flex items-center gap-3">
          <span className="material-icons text-indigo-600">save_alt</span>
          Arquivos de Segurança
        </h2>
        <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest mt-1">Gerencie cópias manuais para segurança extra</p>
      </div>

      <div className="grid grid-cols-1 md:grid-cols-2 gap-8">
        <div className="bg-white rounded-[3rem] p-10 shadow-xl border border-slate-100 flex flex-col items-center text-center group transition-all hover:shadow-2xl">
          <div className="w-20 h-20 bg-indigo-50 rounded-[2rem] flex items-center justify-center mb-8 text-indigo-600 group-hover:scale-110 transition-transform">
            <span className="material-icons text-4xl">download</span>
          </div>
          <h4 className="text-xl font-black text-[#1a1c3d] mb-3 uppercase tracking-tight">Exportar</h4>
          <p className="text-slate-400 text-[10px] font-bold uppercase mb-10 tracking-widest leading-relaxed">Crie uma cópia física dos seus dados para guardar no seu aparelho.</p>
          <button 
            onClick={handleBackup} 
            className="w-full py-6 bg-indigo-600 text-white font-black rounded-[2.5rem] shadow-xl active:scale-95 transition-all text-xs tracking-widest uppercase"
          >
            GERAR ARQUIVO JSON
          </button>
        </div>

        <div className="bg-white rounded-[3rem] p-10 shadow-xl border border-slate-100 flex flex-col items-center text-center group transition-all hover:shadow-2xl">
          <div className="w-20 h-20 bg-emerald-50 rounded-[2rem] flex items-center justify-center mb-8 text-emerald-600 group-hover:scale-110 transition-transform">
            <span className="material-icons text-4xl">upload</span>
          </div>
          <h4 className="text-xl font-black text-[#1a1c3d] mb-3 uppercase tracking-tight">Importar</h4>
          <p className="text-slate-400 text-[10px] font-bold uppercase mb-10 tracking-widest leading-relaxed">Restaurar registros a partir de um arquivo de backup anterior.</p>
          <button 
            onClick={() => fileInputRef.current?.click()} 
            className="w-full py-6 bg-emerald-500 text-white font-black rounded-[2.5rem] shadow-xl active:scale-95 transition-all text-xs tracking-widest uppercase"
          >
            SELECIONAR ARQUIVO
          </button>
          <input type="file" ref={fileInputRef} onChange={handleFileChange} accept=".json" className="hidden" />
        </div>
      </div>

      <div className="bg-[#1a1c3d] rounded-[2.5rem] p-8 text-center border border-white/5">
         <span className="material-icons text-amber-400 text-3xl mb-4">info</span>
         <p className="text-white/60 font-medium text-[11px] leading-relaxed max-w-xs mx-auto">
           A sincronização automática via nuvem pode ser acessada diretamente no <span className="text-white font-black">topo do menu lateral</span>.
         </p>
      </div>
    </div>
  );
};

export default BackupRestore;

export interface ServiceRoles {
  gate: string;      // Portão
  praise: string;    // Louvor
  word: string;      // Palavra (Obreiro selecionado)
  scripture: string; // Texto Bíblico (Livro e versículo digitados)
  leader?: string;   // Dirigente (Usado na quinta-feira)
}

export interface ServiceRecord {
  id: string;
  date: string;
  description: string; // EBD, DOM, ou Dia da Semana
  songs: string[];
  roles: ServiceRoles;
}

export interface ServiceDraft {
  date: string;
  description: string;
  songs: string[];
  roles: ServiceRoles;
}

export interface SongStats {
  song: string;
  count: number;
  lastDate: string | null;
  history: string[];
}

export type LearningStatus = 'not_started' | 'learning' | 'learned' | 'correcting';

export interface PraiseLearningItem {
  song: string;
  status: LearningStatus;
  updatedAt: string;
}

export interface AppData {
  history: ServiceRecord[];
  customSongs?: string[];
  draft?: ServiceDraft;
  learningList?: PraiseLearningItem[];
}

import React, { useState, useEffect, useMemo, useRef } from 'react';
import { INITIAL_PRAISE_LIST } from './constants';
import { ServiceRecord, SongStats, ServiceDraft, PraiseLearningItem } from './types';
import ServiceForm from './components/ServiceForm';
import HistoryList from './components/HistoryList';
import RankingList from './components/RankingList';
import BackupRestore from './components/BackupRestore';
import UnplayedList from './components/UnplayedList';
import WorkerStats from './components/WorkerStats';
import WorkerRanking from './components/WorkerRanking';
import PraiseLearningList from './components/PraiseLearningList';
import { initDB, saveData, loadData } from './db';
import { supabase } from './supabase';
import AuthForm from './components/AuthForm';

const App: React.FC = () => {
  const [activeTab, setActiveTab] = useState<'new' | 'history' | 'workers' | 'suggestions' | 'praise-ranking' | 'unplayed' | 'learning' | 'settings'>('new');
  const [history, setHistory] = useState<ServiceRecord[]>([]);
  const [customSongs, setCustomSongs] = useState<string[]>([]);
  const [learningList, setLearningList] = useState<PraiseLearningItem[]>([]);
  const [isLoading, setIsLoading] = useState(true);
  const [isOffline, setIsOffline] = useState(!navigator.onLine);
  const [editingId, setEditingId] = useState<string | null>(null);
  const [isMobileMenuOpen, setIsMobileMenuOpen] = useState(false);
  const [user, setUser] = useState<any>(null);
  const [syncStatus, setSyncStatus] = useState<'synced' | 'syncing' | 'local'>('local');
  const [showLoginModal, setShowLoginModal] = useState(false);
  const [isCloudActionLoading, setIsCloudActionLoading] = useState(false);

  const [isReadyForCloudSync, setIsReadyForCloudSync] = useState(false);
  const syncTimeoutRef = useRef<number | null>(null);

  const getTodayDate = () => {
    const now = new Date();
    return `${now.getFullYear()}-${String(now.getMonth() + 1).padStart(2, '0')}-${String(now.getDate()).padStart(2, '0')}`;
  };

  const emptyRoles = { gate: '', praise: '', word: '', scripture: '', leader: '' };

  const [draft, setDraft] = useState<ServiceDraft>({
    date: getTodayDate(),
    description: '',
    songs: [],
    roles: { ...emptyRoles }
  });

  useEffect(() => {
    const handleOnline = () => setIsOffline(false);
    const handleOffline = () => setIsOffline(true);
    window.addEventListener('online', handleOnline);
    window.addEventListener('offline', handleOffline);

    const setup = async () => {
      try {
        await initDB();
        const localData = await loadData();

        if (localData) {
          if (localData.history) setHistory(localData.history);
          if (localData.customSongs) setCustomSongs(localData.customSongs);
          if (localData.learningList) setLearningList(localData.learningList);
          if (localData.draft) setDraft({ ...localData.draft, date: getTodayDate() });
        }

        const { data: { session } } = await supabase.auth.getSession();
        const currentUser = session?.user ?? null;
        setUser(currentUser);

        if (currentUser) {
          const { data: cloudData } = await supabase
            .from('user_data')
            .select('json_data')
            .eq('user_id', currentUser.id)
            .maybeSingle();

          if (cloudData?.json_data) {
            const cloud = cloudData.json_data;
            if (localData?.history?.length === 0 && cloud.history?.length > 0) {
              setHistory(cloud.history);
              setCustomSongs(cloud.customSongs || []);
              setLearningList(cloud.learningList || []);
            }
          }
        }
      } catch (e) {
        console.error("Erro no setup inicial:", e);
      } finally {
        setIsLoading(false);
        setIsReadyForCloudSync(true);
      }
    };
    setup();

    const { data: { subscription } } = supabase.auth.onAuthStateChange((_event, session) => {
      setUser(session?.user ?? null);
    });

    return () => {
      window.removeEventListener('online', handleOnline);
      window.removeEventListener('offline', handleOffline);
      subscription.unsubscribe();
    };
  }, []);

  useEffect(() => {
    if (isLoading) return;
    saveData({ history, customSongs, draft, learningList });
  }, [history, customSongs, draft, learningList, isLoading]);

  useEffect(() => {
    if (!isReadyForCloudSync || !user || isOffline) return;

    setSyncStatus('syncing');
    if (syncTimeoutRef.current) window.clearTimeout(syncTimeoutRef.current);

    syncTimeoutRef.current = window.setTimeout(async () => {
      try {
        const { error } = await supabase.from('user_data').upsert({ 
          user_id: user.id, 
          json_data: { history, customSongs, learningList },
          updated_at: new Date().toISOString()
        }, { onConflict: 'user_id' });

        if (error) throw error;
        setSyncStatus('synced');
      } catch (e) {
        console.error("Falha no Auto-Sync Cloud:", e);
        setSyncStatus('local');
      }
    }, 3000);

    return () => {
      if (syncTimeoutRef.current) window.clearTimeout(syncTimeoutRef.current);
    };
  }, [history, customSongs, learningList, user, isOffline, isReadyForCloudSync]);

  const handleManualUpload = async () => {
    if (!user || isOffline) return;
    setIsCloudActionLoading(true);
    try {
      const { error } = await supabase.from('user_data').upsert({
        user_id: user.id,
        json_data: { history, customSongs, learningList },
        updated_at: new Date().toISOString()
      }, { onConflict: 'user_id' });
      if (error) throw error;
      setSyncStatus('synced');
      alert("Dados enviados para a nuvem com sucesso!");
    } catch (e) {
      alert("Erro ao sincronizar dados.");
    } finally {
      setIsCloudActionLoading(false);
    }
  };

  const handleManualDownload = async () => {
    if (!user || isOffline) return;
    if (!window.confirm("Isso substituirá seus dados locais pela versão da nuvem. Continuar?")) return;
    setIsCloudActionLoading(true);
    try {
      const { data } = await supabase.from('user_data').select('json_data').eq('user_id', user.id).maybeSingle();
      if (data?.json_data) {
        setHistory(data.json_data.history || []);
        setCustomSongs(data.json_data.customSongs || []);
        setLearningList(data.json_data.learningList || []);
        alert("Dados recuperados da nuvem!");
      } else {
        alert("Nenhum dado encontrado na nuvem.");
      }
    } catch (e) {
      alert("Erro ao baixar dados.");
    } finally {
      setIsCloudActionLoading(false);
    }
  };

  const fullSongList = useMemo(() => {
    return [...new Set([...INITIAL_PRAISE_LIST, ...customSongs])].sort((a, b) => a.localeCompare(b));
  }, [customSongs]);

  const songStats = useMemo(() => {
    const stats: Record<string, SongStats> = {};
    history.forEach(record => {
      record.songs.forEach(song => {
        if (!stats[song]) stats[song] = { song, count: 0, lastDate: null, history: [] };
        stats[song].count++;
        stats[song].history.push(record.date);
      });
    });
    Object.keys(stats).forEach(s => {
      stats[s].history.sort((a, b) => b.localeCompare(a));
      stats[s].lastDate = stats[s].history[0];
    });
    return stats;
  }, [history]);

  const saveRecord = (data: Omit<ServiceRecord, 'id'>) => {
    if (editingId) {
      setHistory(prev => prev.map(r => r.id === editingId ? { ...data, id: editingId } : r));
      setEditingId(null);
    } else {
      setHistory(prev => [{ ...data, id: crypto.randomUUID() }, ...prev]);
    }
    setDraft({ date: getTodayDate(), description: '', songs: [], roles: { ...emptyRoles } });
  };

  const menuItems = [
    { id: 'new', icon: 'add_circle', label: 'Novo Culto' },
    { id: 'history', icon: 'history', label: 'Histórico' },
    { id: 'learning', icon: 'school', label: 'Aprendizado' },
    { id: 'workers', icon: 'emoji_events', label: 'Ranking Obreiros' },
    { id: 'suggestions', icon: 'assignment_ind', label: 'Escala / Sugestão' },
    { id: 'praise-ranking', icon: 'trending_up', label: 'Ranking Hinos' },
    { id: 'unplayed', icon: 'assignment_late', label: 'Hinos Restantes' },
    { id: 'settings', icon: 'settings', label: 'Backup / Sistema' },
  ] as const;

  const handleTabChange = (id: typeof activeTab) => {
    setActiveTab(id);
    setIsMobileMenuOpen(false);
    window.scrollTo(0,0);
  };

  const AppBrand = () => (
    <div className="flex items-center gap-5">
      <div className="w-16 h-16 bg-white rounded-2xl shadow-xl flex items-center justify-center p-2.5">
        <img src="https://cdn-icons-png.flaticon.com/512/1672/1672225.png" alt="Logo" className="w-full h-full object-contain" />
      </div>
      <div className="flex flex-col">
        <div className="flex items-center gap-2">
           <span className={`material-icons text-[14px] ${syncStatus === 'synced' ? 'text-emerald-400' : syncStatus === 'syncing' ? 'text-amber-400 animate-spin' : 'text-white/20'}`}>
             {syncStatus === 'synced' ? 'cloud_done' : syncStatus === 'syncing' ? 'sync' : 'cloud_off'}
           </span>
           <span className="text-white/60 font-black text-[10px] tracking-[0.2em] uppercase">
             {syncStatus === 'synced' ? 'Nuvem OK' : syncStatus === 'syncing' ? 'Salvando...' : 'Local'}
           </span>
        </div>
        <h1 className="text-white font-black text-xl tracking-tighter leading-tight uppercase whitespace-nowrap">Santo Antônio II</h1>
        <div className="mt-1 bg-white/10 self-start px-3 py-1 rounded-full flex items-center gap-2">
           <span className="material-icons text-amber-400 text-xs">analytics</span>
           <span className="text-white font-black text-[10px] uppercase">{history.length} Cultos</span>
        </div>
      </div>
    </div>
  );

  const UserProfile = () => {
    if (!user) {
      return (
        <div className="px-10 py-8 border-b border-white/5 animate-fadeIn">
          <button 
            onClick={() => setShowLoginModal(true)}
            className="w-full py-5 bg-amber-400 text-[#1a1c3d] rounded-2xl font-black text-[11px] uppercase tracking-widest flex items-center justify-center gap-3 shadow-lg active:scale-95 transition-all"
          >
            <span className="material-icons text-lg">cloud_sync</span>
            Entrar / Sincronizar
          </button>
        </div>
      );
    }
    return (
      <div className="px-10 py-8 border-b border-white/5 space-y-6 bg-white/5 animate-fadeIn">
        <div className="flex items-center gap-4">
          <div className="w-12 h-12 bg-indigo-50 rounded-2xl flex items-center justify-center overflow-hidden border border-white/10 shrink-0">
            <span className="material-icons text-[#1a1c3d] text-2xl">person</span>
          </div>
          <div className="flex flex-col min-w-0 flex-1">
            <span className="text-white font-black text-xs uppercase truncate leading-tight">{user.email?.split('@')[0]}</span>
            <div className="flex items-center gap-1.5 mt-0.5">
              <span className={`w-1.5 h-1.5 rounded-full ${isOffline ? 'bg-rose-500' : 'bg-emerald-400 animate-pulse'}`}></span>
              <span className="text-white/30 font-bold text-[8px] uppercase tracking-widest">{isOffline ? 'Offline' : 'Conectado'}</span>
            </div>
          </div>
          <button 
            onClick={() => supabase.auth.signOut()}
            className="w-10 h-10 bg-rose-500/10 rounded-xl flex items-center justify-center text-rose-400 hover:bg-rose-500/20 transition-all"
            title="Sair"
          >
            <span className="material-icons text-sm">logout</span>
          </button>
        </div>

        <div className="grid grid-cols-2 gap-3">
          <button 
            disabled={isCloudActionLoading || isOffline}
            onClick={handleManualUpload}
            className="flex-1 bg-indigo-500 hover:bg-indigo-600 text-white py-3 rounded-xl flex flex-col items-center justify-center gap-1 transition-all active:scale-95 shadow-lg disabled:opacity-50"
          >
            <span className={`material-icons text-sm ${isCloudActionLoading ? 'animate-spin' : ''}`}>cloud_upload</span>
            <span className="text-[7px] font-black uppercase tracking-widest">Sincronizar</span>
          </button>
          <button 
            disabled={isCloudActionLoading || isOffline}
            onClick={handleManualDownload}
            className="flex-1 bg-amber-400 hover:bg-amber-500 text-[#1a1c3d] py-3 rounded-xl flex flex-col items-center justify-center gap-1 transition-all active:scale-95 shadow-lg disabled:opacity-50"
          >
            <span className={`material-icons text-sm ${isCloudActionLoading ? 'animate-spin' : ''}`}>cloud_download</span>
            <span className="text-[7px] font-black uppercase tracking-widest">Recuperar</span>
          </button>
        </div>
      </div>
    );
  };

  if (isLoading) return <div className="min-h-screen bg-[#1a1c3d] flex flex-col items-center justify-center text-white p-10"><img src="https://cdn-icons-png.flaticon.com/512/1672/1672225.png" className="w-20 h-20 animate-bounce mb-6" /><p className="font-black tracking-widest text-sm animate-pulse">CARREGANDO SISTEMA...</p></div>;

  return (
    <div className="min-h-screen bg-slate-100 flex flex-col md:flex-row">
      <aside className="hidden md:flex w-96 bg-[#1a1c3d] flex-col sticky top-0 h-screen shadow-2xl z-[150]">
        <div className="p-12 border-b border-white/5">
          <AppBrand />
        </div>

        <UserProfile />

        <nav className="flex-1 py-4 overflow-y-auto custom-scrollbar">
          {menuItems.map(item => (
            <button 
              key={item.id}
              onClick={() => handleTabChange(item.id)}
              className={`w-full flex items-center gap-6 px-12 py-6 transition-all duration-300 ${activeTab === item.id ? 'bg-amber-400 text-[#1a1c3d] font-black' : 'text-white/40 hover:text-white hover:bg-white/5'}`}
            >
              <span className="material-icons text-2xl">{item.icon}</span>
              <span className="text-sm uppercase font-black tracking-widest">{item.label}</span>
            </button>
          ))}
        </nav>
      </aside>

      <header className="md:hidden bg-[#1a1c3d] text-white p-6 sticky top-0 z-[200] flex justify-between items-center shadow-2xl rounded-b-[2rem]">
        <AppBrand />
        <button onClick={() => setIsMobileMenuOpen(true)} className="p-4 bg-white/10 rounded-2xl active:scale-90 transition-transform">
          <span className="material-icons text-3xl">menu</span>
        </button>
      </header>

      {isMobileMenuOpen && (
        <div className="fixed inset-0 z-[300] md:hidden">
          <div className="absolute inset-0 bg-[#1a1c3d]/90 backdrop-blur-lg" onClick={() => setIsMobileMenuOpen(false)}></div>
          <div className="absolute top-0 right-0 bottom-0 w-[85%] bg-[#1a1c3d] shadow-2xl flex flex-col animate-slideInRight border-l border-white/5">
            <div className="p-10 flex justify-between items-center border-b border-white/5">
              <span className="text-white/40 font-black text-xs tracking-widest uppercase">Navegação Principal</span>
              <button onClick={() => setIsMobileMenuOpen(false)} className="w-12 h-12 bg-white/5 rounded-full flex items-center justify-center text-white/40"><span className="material-icons">close</span></button>
            </div>

            <UserProfile />

            <nav className="flex-1 py-4 overflow-y-auto">
              {menuItems.map(item => (
                <button 
                  key={item.id}
                  onClick={() => handleTabChange(item.id)}
                  className={`w-full flex items-center gap-8 px-10 py-7 border-b border-white/5 ${activeTab === item.id ? 'text-amber-400 bg-white/5 font-black' : 'text-white/60'}`}
                >
                  <span className="material-icons text-3xl">{item.icon}</span>
                  <span className="text-base font-black uppercase tracking-widest">{item.label}</span>
                </button>
              ))}
            </nav>
          </div>
        </div>
      )}

      {showLoginModal && (
        <div className="fixed inset-0 z-[9999] flex items-center justify-center p-6">
          <div className="absolute inset-0 bg-[#1a1c3d]/95 backdrop-blur-xl animate-fadeIn" onClick={() => setShowLoginModal(false)} />
          <div className="relative bg-white/5 border border-white/10 rounded-[3rem] p-10 w-full max-w-sm shadow-2xl animate-scaleUp">
            <div className="flex flex-col items-center text-center mb-8">
              <div className="w-20 h-20 bg-amber-400 rounded-3xl flex items-center justify-center mb-6 shadow-xl shadow-amber-400/20">
                <span className="material-icons text-4xl text-[#1a1c3d]">cloud_sync</span>
              </div>
              <h2 className="text-white font-black text-2xl uppercase tracking-tighter">Sincronizar</h2>
              <p className="text-white/40 font-bold text-[10px] uppercase tracking-widest mt-2 leading-relaxed">Acesse sua conta para manter seus dados seguros em qualquer lugar.</p>
            </div>
            <AuthForm onSuccess={() => setShowLoginModal(false)} />
            <button 
              onClick={() => setShowLoginModal(false)}
              className="w-full mt-6 py-4 text-white/20 font-black text-[10px] uppercase tracking-widest hover:text-white transition-all"
            >
              FECHAR
            </button>
          </div>
        </div>
      )}

      <main className="flex-1 min-w-0">
        {isOffline && <div className="bg-amber-500 text-white text-[10px] font-black uppercase py-2.5 text-center sticky top-[92px] md:top-0 z-[190] shadow-lg">Você está operando offline.</div>}

        <div className="px-4 pt-14 pb-20 md:p-16 animate-fadeIn max-w-6xl mx-auto">
          {activeTab === 'new' && <ServiceForm onSave={saveRecord} songStats={songStats} fullSongList={fullSongList} onRegisterNewSong={s => setCustomSongs(prev => [...prev, s])} draft={draft} setDraft={setDraft} editingId={editingId} onCancelEdit={() => setEditingId(null)} />}
          {activeTab === 'history' && <HistoryList history={history} onDelete={id => setHistory(prev => prev.filter(r => r.id !== id))} onEdit={r => { setEditingId(r.id); setDraft({ ...r }); setActiveTab('new'); }} onClearAll={() => {}} />}
          {activeTab === 'learning' && <PraiseLearningList fullSongList={fullSongList} learningList={learningList} setLearningList={setLearningList} />}
          {activeTab === 'workers' && <WorkerRanking history={history} />}
          {activeTab === 'suggestions' && <WorkerStats history={history} />}
          {activeTab === 'praise-ranking' && <RankingList songStats={songStats} />}
          {activeTab === 'unplayed' && <UnplayedList fullSongList={INITIAL_PRAISE_LIST} history={history} />}
          {activeTab === 'settings' && <BackupRestore history={history} customSongs={customSongs} learningList={learningList} onRestore={(h, c, l) => { setHistory(h); setCustomSongs(c); setLearningList(l || []); }} />}
        </div>
      </main>
    </div>
  );
};

export default App;

import React, { useState, useMemo, useEffect } from 'react';
import { ServiceRecord, SongStats, ServiceDraft } from '../types';
import { WORKERS_LIST } from '../constants';

const Label = ({ children }: { children?: React.ReactNode }) => (
  <label className="text-[10px] md:text-[11px] font-black text-slate-400 uppercase tracking-widest block mb-2 text-center md:text-left">{children}</label>
);

const FormInput = ({ children, className = "" }: { children?: React.ReactNode, className?: string }) => (
  <div className={`bg-slate-50 border border-slate-100 rounded-2xl px-4 py-3 shadow-sm transition-all focus-within:shadow-md focus-within:bg-white focus-within:border-indigo-100 ${className}`}>
    {children}
  </div>
);

interface Props {
  onSave: (record: Omit<ServiceRecord, 'id'>) => void;
  songStats: Record<string, SongStats>;
  fullSongList: string[];
  onRegisterNewSong: (song: string) => void;
  draft: ServiceDraft;
  setDraft: React.Dispatch<React.SetStateAction<ServiceDraft>>;
  editingId: string | null;
  onCancelEdit: () => void;
}

const ServiceForm: React.FC<Props> = ({ onSave, songStats, fullSongList, onRegisterNewSong, draft, setDraft, editingId, onCancelEdit }) => {
  const [inputValue, setInputValue] = useState('');
  const [showSuggestions, setShowSuggestions] = useState(false);
  const [pendingSong, setPendingSong] = useState<{name: string, diff: number, lastDate: string} | null>(null);
  const [draggedIndex, setDraggedIndex] = useState<number | null>(null);
  const [showSuccessModal, setShowSuccessModal] = useState(false);

  const dayOfWeekNames = ['DOM', 'SEG', 'TER', 'QUA', 'QUI', 'SEX', 'SÁB'];
  const fullDayNames = ['DOMINGO', 'SEGUNDA-FEIRA', 'TERÇA-FEIRA', 'QUARTA-FEIRA', 'QUINTA-FEIRA', 'SEXTA-FEIRA', 'SÁBADO'];

  const dateInfo = useMemo(() => {
    const d = new Date(draft.date + 'T12:00:00');
    const dayIndex = d.getDay();
    return { 
      name: dayOfWeekNames[dayIndex], 
      fullName: fullDayNames[dayIndex], 
      isSunday: dayIndex === 0, 
      isMonday: dayIndex === 1, 
      isWednesday: dayIndex === 3,
      isThursday: dayIndex === 4 
    };
  }, [draft.date]);

  useEffect(() => {
    if (!dateInfo.isSunday && !editingId) setDraft(prev => ({ ...prev, description: dateInfo.fullName }));
    else if (dateInfo.isSunday && !editingId && !['EBD', 'DOM'].includes(draft.description)) setDraft(prev => ({ ...prev, description: 'DOM' }));
  }, [dateInfo, editingId]);

  const updateRole = (role: keyof typeof draft.roles, name: string) => {
    setDraft(prev => ({ ...prev, roles: { ...prev.roles, [role]: name } }));
  };

  const handleSave = () => {
    onSave(draft);
    setShowSuccessModal(true);
  };

  const checkAndAddSong = (songName: string) => {
    const name = songName.trim();
    if (!name) return;
    if (!fullSongList.includes(name)) onRegisterNewSong(name);

    const stats = songStats[name];
    if (stats && stats.lastDate) {
      const lastDate = new Date(stats.lastDate + 'T12:00:00');
      const today = new Date(); today.setHours(12, 0, 0, 0);
      const diffDays = Math.ceil(Math.abs(today.getTime() - lastDate.getTime()) / (1000 * 60 * 60 * 24));

      if (diffDays <= 30) { 
        setPendingSong({ name, diff: diffDays, lastDate: stats.lastDate }); 
        return; 
      }
    }
    executeAdd(name);
  };

  const executeAdd = (name: string) => {
    setDraft(prev => ({ ...prev, songs: [...prev.songs, name] }));
    setInputValue('');
    setShowSuggestions(false);
    setPendingSong(null);
  };

  const shareDraftPraise = () => {
    const dateFormatted = new Date(draft.date + 'T12:00:00').toLocaleDateString('pt-BR');
    let msg = `*LOUVORES ICM SANTO ANTÔNIO II*\nData: ${dateFormatted}\n\n`;
    draft.songs.forEach((s, i) => msg += `${i + 1}. ${s}\n`);
    window.open(`https://wa.me/?text=${encodeURIComponent(msg)}`, '_blank');
  };

  const onDragStart = (e: React.DragEvent, index: number) => {
    setDraggedIndex(index);
  };

  const onDragOver = (e: React.DragEvent, index: number) => {
    e.preventDefault();
    if (draggedIndex === null || draggedIndex === index) return;
    const newSongs = [...draft.songs];
    const item = newSongs[draggedIndex];
    newSongs.splice(draggedIndex, 1);
    newSongs.splice(index, 0, item);
    setDraggedIndex(index);
    setDraft(prev => ({ ...prev, songs: newSongs }));
  };

  const suggestions = useMemo(() => {
    if (inputValue.length < 1) return [];
    const lowerInput = inputValue.toLowerCase();
    return fullSongList
      .filter(s => s.toLowerCase().includes(lowerInput))
      .sort((a, b) => {
        const aIsCias = a.startsWith('(CIAS)');
        const bIsCias = b.startsWith('(CIAS)');
        if (aIsCias && !bIsCias) return 1;
        if (!aIsCias && bIsCias) return -1;
        return 0; 
      })
      .slice(0, 30);
  }, [inputValue, fullSongList]);

  return (
    <>
      {showSuccessModal && (
        <div className="fixed inset-0 z-[9999] flex items-center justify-center p-6">
          <div className="absolute inset-0 bg-[#1a1c3d]/90 backdrop-blur-md animate-fadeIn" onClick={() => setShowSuccessModal(false)} />
          <div className="relative bg-white rounded-[3.5rem] p-10 w-full max-w-sm shadow-2xl animate-scaleUp text-center border border-white">
            <div className="w-20 h-20 bg-emerald-50 rounded-full flex items-center justify-center mx-auto mb-6 text-emerald-500">
              <span className="material-icons text-4xl">check_circle</span>
            </div>
            <h3 className="text-2xl font-black text-[#1a1c3d] mb-2 uppercase tracking-tighter">Relatório Salvo!</h3>
            <p className="text-slate-400 font-bold text-[10px] uppercase tracking-[0.2em] mb-8">Dados registrados com sucesso.</p>
            <button 
              onClick={() => setShowSuccessModal(false)} 
              className="w-full py-5 bg-[#1a1c3d] text-white font-black rounded-3xl shadow-lg active:scale-95 transition-all uppercase text-xs tracking-widest"
            >
              OK, CONTINUAR
            </button>
          </div>
        </div>
      )}

      <div className="max-w-xl mx-auto space-y-6 animate-fadeIn pb-20">
        <div className="bg-white rounded-[3rem] shadow-2xl p-6 md:p-12 border border-white">
          <div className="space-y-8">
            <div className="grid grid-cols-1 gap-6">
              <div className="flex flex-col items-center">
                <Label>Data do Culto</Label>
                <FormInput className="w-full">
                  <input 
                    type="date" 
                    value={draft.date} 
                    onChange={(e) => setDraft(prev => ({ ...prev, date: e.target.value }))} 
                    className="w-full bg-transparent font-black text-lg md:text-xl text-[#1a1c3d] text-center outline-none" 
                  />
                </FormInput>
                <div className="mt-2 bg-indigo-50 px-4 py-1 rounded-full">
                  <span className="text-indigo-600 font-black text-[9px] uppercase tracking-widest">DIA: {dateInfo.name}</span>
                </div>
              </div>

              {dateInfo.isSunday && (
                <div className="flex flex-col">
                  <Label>Período</Label>
                  <div className="flex bg-slate-50 border border-slate-100 p-1 rounded-2xl">
                    <button onClick={() => setDraft(prev => ({ ...prev, description: 'EBD' }))} className={`flex-1 py-2.5 text-[11px] font-black rounded-xl transition-all ${draft.description === 'EBD' ? 'bg-[#1a1c3d] text-white shadow-lg' : 'text-slate-400'}`}>EBD</button>
                    <button onClick={() => setDraft(prev => ({ ...prev, description: 'DOM' }))} className={`flex-1 py-2.5 text-[11px] font-black rounded-xl transition-all ${draft.description === 'DOM' ? 'bg-[#1a1c3d] text-white shadow-lg' : 'text-slate-400'}`}>DOM</button>
                  </div>
                </div>
              )}
            </div>

            <div className="space-y-4 pt-6 border-t border-slate-50">
              <Label>Hinos</Label>
              <div className="flex gap-2">
                <input 
                  type="text" 
                  value={inputValue} 
                  onChange={e => {setInputValue(e.target.value); setShowSuggestions(true);}} 
                  className="flex-1 px-5 py-3.5 bg-slate-50 border border-slate-100 rounded-2xl font-bold text-sm text-slate-700 outline-none focus:ring-4 focus:ring-indigo-50 focus:bg-white transition-all shadow-sm" 
                  placeholder="Hino ou Nº..." 
                />
                <button onClick={() => checkAndAddSong(inputValue)} className="bg-[#1a1c3d] text-white w-12 h-12 rounded-xl flex items-center justify-center active:scale-90 transition-transform shadow-lg shrink-0"><span className="material-icons text-xl">add</span></button>
              </div>
              {showSuggestions && suggestions.length > 0 && (
                <div className="absolute z-[250] w-[calc(100%-3rem)] md:w-[calc(100%-6rem)] bg-white shadow-2xl rounded-2xl overflow-hidden border border-slate-100 max-h-60 overflow-y-auto mt-1 animate-fadeIn">
                  {suggestions.map(s => (
                    <div key={s} onMouseDown={() => checkAndAddSong(s)} className="p-4 hover:bg-slate-50 cursor-pointer border-b border-slate-50 font-bold text-xs text-slate-700 flex justify-between items-center">
                      <span className={s.startsWith('(CIAS)') ? 'text-slate-400' : 'text-[#1a1c3d]'}>{s}</span>
                      <span className="material-icons text-indigo-400 text-sm">add_circle</span>
                    </div>
                  ))}
                </div>
              )}

              <div className="space-y-3">
                <div className="flex justify-between items-center px-1">
                  <span className="text-[9px] font-black text-slate-400 uppercase tracking-widest">Hinos Selecionados</span>
                  {draft.songs.length > 0 && (
                    <button onClick={shareDraftPraise} className="flex items-center gap-1.5 text-[9px] font-black text-emerald-600 bg-emerald-50 px-3 py-1 rounded-full border border-emerald-100 hover:bg-emerald-100 transition-colors">
                      <span className="material-icons text-xs">share</span> COMPARTILHAR
                    </button>
                  )}
                </div>
                <div className="space-y-2 max-h-80 overflow-y-auto pr-1 custom-scrollbar">
                  {draft.songs.map((s, i) => (
                    <div 
                      key={`${s}-${i}`} 
                      draggable 
                      onDragStart={(e) => onDragStart(e, i)}
                      onDragOver={(e) => onDragOver(e, i)}
                      onDragEnd={() => setDraggedIndex(null)}
                      className={`flex items-center justify-between p-3.5 bg-slate-50/50 rounded-xl border border-slate-100 cursor-move transition-all active:scale-95 hover:bg-white hover:shadow-md ${draggedIndex === i ? 'opacity-50' : ''}`}
                    >
                      <div className="flex items-center gap-3 overflow-hidden">
                        <span className="material-icons text-slate-300 text-sm">drag_indicator</span>
                        <span className="font-bold text-slate-700 text-[13px] truncate">#{i+1} {s}</span>
                      </div>
                      <button onClick={() => setDraft(prev => ({...prev, songs: prev.songs.filter((_, idx) => idx !== i)}))} className="text-rose-200 hover:text-rose-500 ml-2"><span className="material-icons text-lg">close</span></button>
                    </div>
                  ))}
                </div>
              </div>
            </div>

            <div className="space-y-5 pt-6 border-t border-slate-50">
              <div className="flex flex-col">
                <Label>Portão</Label>
                <FormInput>
                  <select 
                    value={draft.roles.gate} 
                    onChange={e => updateRole('gate', e.target.value)} 
                    className="w-full bg-transparent font-black text-base text-[#1a1c3d] text-center outline-none appearance-none cursor-pointer"
                  >
                    <option value="">Selecione...</option>
                    {WORKERS_LIST.map(n => <option key={n} value={n}>{n}</option>)}
                  </select>
                </FormInput>
              </div>

              {dateInfo.isWednesday && (
                <div className="bg-indigo-50/80 p-4 rounded-2xl border border-indigo-100 flex items-center justify-center gap-3 text-indigo-700">
                  <span className="text-lg">🌸</span>
                  <span className="font-black text-[9px] uppercase tracking-widest text-center leading-tight">Culto do Grupo de Senhoras</span>
                </div>
              )}

              {dateInfo.isThursday && (
                <div className="flex flex-col">
                  <Label>Dirigente (Único)</Label>
                  <FormInput>
                    <select 
                      value={draft.roles.leader} 
                      onChange={e => updateRole('leader', e.target.value)} 
                      className="w-full bg-transparent font-black text-base text-[#1a1c3d] text-center outline-none appearance-none cursor-pointer"
                    >
                      <option value="">Selecione...</option>
                      {WORKERS_LIST.map(n => <option key={n} value={n}>{n}</option>)}
                    </select>
                  </FormInput>
                </div>
              )}

              {!dateInfo.isWednesday && !dateInfo.isThursday && (
                <div className="space-y-5">
                  <div className="flex flex-col">
                    <Label>Louvor</Label>
                    <FormInput>
                      <select value={draft.roles.praise} onChange={e => updateRole('praise', e.target.value)} className="w-full bg-transparent font-black text-base text-[#1a1c3d] text-center outline-none appearance-none cursor-pointer">
                        <option value="">Selecione...</option>
                        {WORKERS_LIST.map(n => <option key={n} value={n}>{n}</option>)}
                      </select>
                    </FormInput>
                  </div>

                  {!dateInfo.isMonday && (
                    <div className="flex flex-col">
                      <Label>Palavra</Label>
                      <FormInput>
                        <select value={draft.roles.word} onChange={e => updateRole('word', e.target.value)} className="w-full bg-transparent font-black text-base text-[#1a1c3d] text-center outline-none appearance-none cursor-pointer">
                          <option value="">Selecione...</option>
                          {WORKERS_LIST.map(n => <option key={n} value={n}>{n}</option>)}
                        </select>
                      </FormInput>
                    </div>
                  )}
                </div>
              )}

              {/* Texto Bíblico visível em todos exceto na transmissão ou quando não houver word */}
              {!dateInfo.isWednesday && (
                <div className="flex flex-col min-h-[70px] justify-end">
                  {draft.roles.word === 'TRANSMISSÃO' ? (
                    <div className="bg-amber-50 p-4 rounded-2xl border border-amber-100 flex items-center justify-center gap-3 text-amber-700 animate-fadeIn">
                      <span className="text-lg">📡</span>
                      <span className="font-black text-[9px] uppercase tracking-widest text-center leading-tight">Transmissão via satélite</span>
                    </div>
                  ) : (
                    <>
                      <Label>Texto Bíblico</Label>
                      <FormInput>
                        <input type="text" value={draft.roles.scripture} onChange={e => updateRole('scripture', e.target.value)} placeholder="Livro / Versículo" className="w-full bg-transparent font-black text-base text-[#1a1c3d] text-center outline-none" />
                      </FormInput>
                    </>
                  )}
                </div>
              )}
            </div>

            <button 
              onClick={handleSave} 
              disabled={draft.songs.length === 0} 
              className={`w-full py-5 rounded-2xl font-black text-base tracking-widest transition-all active:scale-95 flex items-center justify-center gap-3 shadow-xl ${draft.songs.length > 0 ? 'bg-[#1a1c3d] text-white' : 'bg-slate-200 text-slate-400 cursor-not-allowed shadow-none'}`}
            >
              <span className="material-icons">save</span>
              {editingId ? 'ATUALIZAR' : 'FINALIZAR'}
            </button>

            {editingId && (
              <button 
                onClick={onCancelEdit}
                className="w-full py-3 text-slate-400 font-black uppercase text-[10px] tracking-widest hover:text-rose-500 transition-colors"
              >
                CANCELAR
              </button>
            )}
          </div>
        </div>
      </div>

      {pendingSong && (
        <div className="fixed inset-0 z-[8000] flex flex-col justify-end">
          <div className="absolute inset-0 bg-black/40 backdrop-blur-sm animate-fadeIn" onClick={() => setPendingSong(null)} />
          <div className="relative bg-white rounded-t-[3rem] p-8 pb-12 shadow-2xl animate-slideUp">
            <div className="w-12 h-1.5 bg-slate-100 rounded-full mx-auto mb-8"></div>
            <div className="flex flex-col items-center text-center">
              <div className="w-16 h-16 bg-amber-50 rounded-full flex items-center justify-center mb-6 text-amber-500">
                <span className="material-icons text-3xl">warning_amber</span>
              </div>
              <h3 className="text-xl font-black text-[#1a1c3d] mb-2 uppercase tracking-tighter">Hino Recorrente</h3>
              <p className="text-slate-500 font-bold mb-8 leading-relaxed text-[11px]">Cantado há apenas <span className="text-amber-600 font-black">{pendingSong.diff} dias</span>. Deseja prosseguir?</p>

              <div className="w-full flex flex-col gap-3">
                <button onClick={() => executeAdd(pendingSong.name)} className="w-full py-5 bg-indigo-600 text-white font-black rounded-2xl shadow-xl active:scale-95">CONFIRMAR E ADICIONAR</button>
                <button onClick={() => setPendingSong(null)} className="w-full py-4 text-slate-400 font-black uppercase text-[10px] tracking-widest">CANCELAR</button>
              </div>
            </div>
          </div>
        </div>
      )}
    </>
  );
};

export default ServiceForm;

import React, { useState, useMemo } from 'react';
import { ServiceRecord } from '../types';

interface Props {
  history: ServiceRecord[];
  onDelete: (id: string) => void;
  onEdit: (record: ServiceRecord) => void;
  onClearAll: () => void;
  externalFilter?: { worker: string; role: string } | null;
  onClearExternalFilter?: () => void;
}

const HistoryList: React.FC<Props> = ({ 
  history, 
  onDelete, 
  onEdit, 
  externalFilter, 
  onClearExternalFilter 
}) => {
  const [searchTerm, setSearchTerm] = useState('');
  const [itemToDelete, setItemToDelete] = useState<string | null>(null);
  const [isMonthPickerOpen, setIsMonthPickerOpen] = useState(false);

  const monthNames = ["JANEIRO", "FEVEREIRO", "MARÇO", "ABRIL", "MAIO", "JUNHO", "JULHO", "AGOSTO", "SETEMBRO", "OUTUBRO", "NOVEMBRO", "DEZEMBRO"];
  const dayOfWeekNamesShort = ['DOM', 'SEG', 'TER', 'QUA', 'QUI', 'SEX', 'SÁB'];

  const groupedHistory = useMemo(() => {
    let filtered = [...history];

    if (externalFilter) {
      filtered = filtered.filter(r => 
        r.roles[externalFilter.role as keyof typeof r.roles] === externalFilter.worker
      );
    }

    if (searchTerm) {
      filtered = filtered.filter(r => 
        r.date.includes(searchTerm) || 
        r.roles?.word?.toLowerCase().includes(searchTerm.toLowerCase()) || 
        r.roles?.praise?.toLowerCase().includes(searchTerm.toLowerCase()) || 
        r.roles?.gate?.toLowerCase().includes(searchTerm.toLowerCase()) || 
        r.roles?.leader?.toLowerCase().includes(searchTerm.toLowerCase()) || 
        r.songs.some(s => s.toLowerCase().includes(searchTerm.toLowerCase()))
      );
    }

    filtered.sort((a, b) => b.date.localeCompare(a.date));

    const groups: Record<string, ServiceRecord[]> = {};
    filtered.forEach(record => {
      const date = new Date(record.date + 'T12:00:00');
      const key = `${monthNames[date.getMonth()]} / ${date.getFullYear()}`;
      if (!groups[key]) groups[key] = [];
      groups[key].push(record);
    });
    return groups;
  }, [history, searchTerm, externalFilter]);

  const roleLabels: Record<string, string> = {
    gate: 'PORTÃO',
    praise: 'LOUVOR',
    word: 'PALAVRA',
    leader: 'DIRIGENTE'
  };

  const InfoTag = ({ label, value, icon, roleId }: { label: string, value?: string, icon: string, roleId: string }) => {
    if (!value) return null;

    const isHighlighted = externalFilter?.role === roleId;

    return (
      <div className={`flex flex-col border-l-2 pl-3 py-1 transition-all rounded-r-xl ${
        isHighlighted 
          ? 'border-amber-400 bg-amber-50/50 ring-1 ring-amber-100' 
          : 'border-indigo-100'
      }`}>
        <div className="flex items-center gap-1 mb-0.5">
          <span className={`material-icons text-[10px] ${isHighlighted ? 'text-amber-500' : 'text-slate-300'}`}>{icon}</span>
          <span className={`text-[8px] font-black uppercase tracking-widest ${isHighlighted ? 'text-amber-600' : 'text-slate-300'}`}>{label}</span>
        </div>
        <span className={`text-[11px] font-black truncate ${isHighlighted ? 'text-[#1a1c3d]' : 'text-slate-600'}`}>{value}</span>
      </div>
    );
  };

  const formatServiceMessage = (r: ServiceRecord) => {
    const d = new Date(r.date + 'T12:00:00');
    const dayName = d.toLocaleDateString('pt-BR', { weekday: 'long' }).toUpperCase();
    const dateFormatted = d.toLocaleDateString('pt-BR');
    const isWednesday = d.getDay() === 3;
    const isThursday = d.getDay() === 4;

    let msg = `RELATÓRIO DE CULTO\n`;
    msg += `ICM SANTO ANTÔNIO II\n\n`;
    msg += `DATA: ${dateFormatted} (${dayName})\n`;

    if (isWednesday) {
      msg += `*CULTO DIRIGIDO PELO GRUPO DE SENHORAS*\n`;
      if (r.roles.gate) msg += `> Portão: ${r.roles.gate}\n`;
    } else if (isThursday) {
      if (r.roles.gate) msg += `> Portão: ${r.roles.gate}\n`;
      if (r.roles.leader) msg += `> Dirigente: ${r.roles.leader}\n`;
      if (r.roles.scripture) msg += `> Texto: ${r.roles.scripture}\n`;
    } else {
      if (r.roles.gate) msg += `> Portão: ${r.roles.gate}\n`;
      if (r.roles.praise) msg += `> Louvor: ${r.roles.praise}\n`;
      if (r.roles.word) msg += `> Palavra: ${r.roles.word}\n`;
      if (r.roles.scripture) msg += `> Texto: ${r.roles.scripture}\n`;
    }

    if (r.songs && r.songs.length > 0) {
      msg += `Louvores: \n`;
      r.songs.forEach((s) => msg += ` - ${s}\n`);
    }
    return msg;
  };

  const shareMonth = (monthKey: string) => {
    const records = (groupedHistory as Record<string, ServiceRecord[]>)[monthKey];
    if (!records) return;
    let msg = `*RESUMO MENSAL - ${monthKey}*\n\n`;
    records.forEach(r => {
      msg += formatServiceMessage(r);
      msg += `-------------------\n\n`;
    });
    window.open(`https://wa.me/?text=${encodeURIComponent(msg)}`, '_blank');
  };

  return (
    <div className="space-y-8 animate-fadeIn max-w-4xl mx-auto pb-10 px-1">
      <div className="space-y-4">
        <div className="flex items-center gap-2">
          <div className="flex-1 bg-white rounded-full flex items-center px-6 py-4 shadow-xl border border-slate-50">
            <span className="material-icons text-slate-300 mr-3">search</span>
            <input 
              type="text" 
              value={searchTerm} 
              onChange={e => setSearchTerm(e.target.value)} 
              placeholder="Pesquisar histórico..." 
              className="w-full bg-transparent font-bold text-slate-600 outline-none placeholder:text-slate-300" 
            />
          </div>
          <button onClick={() => setIsMonthPickerOpen(true)} className="bg-indigo-500 text-white w-14 h-14 rounded-full flex items-center justify-center shadow-xl shrink-0 active:scale-90 transition-transform">
             <span className="material-icons">calendar_month</span>
          </button>
        </div>

        {externalFilter && (
          <div className="bg-[#1a1c3d] rounded-3xl p-5 shadow-2xl animate-scaleUp border border-white/5 relative overflow-hidden">
            <div className="absolute right-0 top-0 opacity-10">
              <span className="material-icons text-7xl -mr-4 -mt-4 text-white">filter_alt</span>
            </div>
            <div className="relative z-10 flex justify-between items-center">
              <div className="flex items-center gap-4">
                <div className="w-12 h-12 bg-amber-400 rounded-2xl flex items-center justify-center text-[#1a1c3d] shadow-lg">
                  <span className="material-icons">person_search</span>
                </div>
                <div className="flex flex-col">
                  <span className="text-[9px] font-black text-white/40 uppercase tracking-[0.2em] mb-1">Filtro de Atividade</span>
                  <p className="text-white text-sm font-medium leading-none">
                    <span className="font-black text-amber-400">{externalFilter.worker}</span>
                    <span className="mx-2 text-white/20">|</span>
                    <span className="font-black uppercase text-[10px] tracking-widest">{roleLabels[externalFilter.role]}</span>
                  </p>
                </div>
              </div>
              <button 
                onClick={onClearExternalFilter}
                className="bg-white/10 hover:bg-white/20 text-white px-4 py-2 rounded-xl text-[10px] font-black uppercase tracking-widest transition-all active:scale-95"
              >
                Limpar
              </button>
            </div>
          </div>
        )}
      </div>

      {(Object.entries(groupedHistory) as [string, ServiceRecord[]][]).map(([month, records]) => (
        <div key={month} className="space-y-4">
          <div className="px-4 flex justify-between items-center">
            <h3 className="text-xs font-black text-slate-400 uppercase tracking-[0.3em]">{month}</h3>
            <span className="text-[10px] font-black text-indigo-300">{records.length} Cultos</span>
          </div>

          <div className="grid gap-4">
            {records.map(record => {
              const d = new Date(record.date + 'T12:00:00');
              const isThursday = d.getDay() === 4;

              return (
                <div key={record.id} className="bg-white rounded-[2.5rem] p-6 md:p-8 shadow-sm border border-slate-100 animate-fadeIn hover:shadow-md transition-shadow">
                  <div className="flex flex-col gap-6">
                    <div className="flex flex-col md:flex-row md:items-center justify-between gap-4">
                      <div className="flex items-center gap-4">
                        <div className="w-12 h-12 bg-slate-50 rounded-2xl flex flex-col items-center justify-center border border-slate-100 shrink-0">
                          <span className="text-[10px] font-black text-indigo-600 leading-none">{d.getDate()}</span>
                          <span className="text-[8px] font-bold text-slate-400 uppercase">{dayOfWeekNamesShort[d.getDay()]}</span>
                        </div>
                        <div className="min-w-0">
                          <h4 className="font-black text-[#1a1c3d] uppercase text-sm tracking-tight truncate">{record.description}</h4>
                          <p className="text-[10px] font-bold text-slate-400 uppercase tracking-widest">{record.songs.length} Louvores</p>
                        </div>
                      </div>

                      <div className="flex items-center gap-2 justify-end">
                        <button onClick={() => window.open(`https://wa.me/?text=${encodeURIComponent(formatServiceMessage(record))}`)} className="w-10 h-10 flex items-center justify-center text-emerald-500 bg-emerald-50/50 rounded-xl active:scale-90"><span className="material-icons text-xl">share</span></button>
                        <button onClick={() => onEdit(record)} className="w-10 h-10 flex items-center justify-center text-indigo-500 bg-indigo-50/50 rounded-xl active:scale-90"><span className="material-icons text-xl">edit</span></button>
                        <button onClick={() => setItemToDelete(record.id)} className="w-10 h-10 flex items-center justify-center text-rose-300 hover:text-rose-500 bg-rose-50/50 rounded-xl active:scale-90"><span className="material-icons text-xl">delete_outline</span></button>
                      </div>
                    </div>

                    <div className={`grid ${isThursday ? 'grid-cols-2 sm:grid-cols-3' : 'grid-cols-2 sm:grid-cols-4'} gap-3 border-t border-slate-50 pt-5`}>
                      <InfoTag label="Portão" value={record.roles.gate} icon="door_front" roleId="gate" />

                      {isThursday ? (
                        <InfoTag label="Dirigente" value={record.roles.leader} icon="stars" roleId="leader" />
                      ) : (
                        <>
                          <InfoTag label="Louvor" value={record.roles.praise} icon="music_note" roleId="praise" />
                          <InfoTag label="Palavra" value={record.roles.word} icon="record_voice_over" roleId="word" />
                        </>
                      )}

                      <InfoTag label="Texto" value={record.roles.word === 'TRANSMISSÃO' ? 'SATÉLITE' : record.roles.scripture} icon="auto_stories" roleId="scripture" />
                    </div>

                    {record.songs.length > 0 && (
                      <div className="pt-4 border-t border-slate-50">
                        <div className="flex flex-wrap gap-2">
                          {record.songs.map((song, idx) => (
                            <div key={idx} className="bg-slate-50 px-3 py-1.5 rounded-lg border border-slate-100 flex items-center gap-2">
                              <span className="text-[8px] font-black text-indigo-300">#{idx + 1}</span>
                              <span className="text-[10px] font-bold text-slate-500 uppercase truncate max-w-[150px]">{song}</span>
                            </div>
                          ))}
                        </div>
                      </div>
                    )}
                  </div>
                </div>
              );
            })}
          </div>
        </div>
      ))}

      {isMonthPickerOpen && (
        <div className="fixed inset-0 z-[8000] flex flex-col justify-end">
          <div className="absolute inset-0 bg-[#1a1c3d]/80 backdrop-blur-sm animate-fadeIn" onClick={() => setIsMonthPickerOpen(false)} />
          <div className="relative bg-white rounded-t-[3rem] p-8 max-h-[85vh] flex flex-col shadow-2xl animate-slideUp">
            <div className="w-12 h-1.5 bg-slate-100 rounded-full mx-auto mb-8 shrink-0"></div>
            <h3 className="text-xl font-black text-[#1a1c3d] mb-6 uppercase tracking-tighter text-center">Exportar Mensal</h3>
            <div className="space-y-2 overflow-y-auto pr-1 custom-scrollbar pb-8">
              {Object.keys(groupedHistory).map(monthKey => (
                <button 
                  key={monthKey}
                  onClick={() => { shareMonth(monthKey); setIsMonthPickerOpen(false); }}
                  className="w-full py-5 px-6 bg-slate-50 hover:bg-indigo-50 text-[#1a1c3d] font-bold rounded-2xl flex justify-between items-center transition-all active:scale-95"
                >
                  <span className="text-sm uppercase tracking-tight">{monthKey}</span>
                  <span className="material-icons text-indigo-400">share</span>
                </button>
              ))}
            </div>
            <button onClick={() => setIsMonthPickerOpen(false)} className="w-full py-4 text-slate-400 font-black uppercase text-[10px] tracking-widest shrink-0">FECHAR</button>
          </div>
        </div>
      )}

      {itemToDelete && (
        <div className="fixed inset-0 z-[8000] flex flex-col justify-end">
          <div className="absolute inset-0 bg-black/40 backdrop-blur-sm animate-fadeIn" onClick={() => setItemToDelete(null)} />
          <div className="relative bg-white rounded-t-[3rem] p-8 pb-12 shadow-2xl animate-slideUp">
            <div className="w-12 h-1.5 bg-slate-100 rounded-full mx-auto mb-8"></div>
            <div className="flex flex-col items-center text-center">
              <div className="w-16 h-16 bg-rose-50 rounded-full flex items-center justify-center mb-6 text-rose-500">
                <span className="material-icons text-3xl">delete_forever</span>
              </div>
              <h3 className="text-xl font-black text-[#1a1c3d] mb-2 uppercase tracking-tighter">Apagar Registro?</h3>
              <p className="text-slate-400 font-bold text-[10px] uppercase mb-8">Esta ação não pode ser desfeita.</p>
              <div className="w-full flex flex-col gap-3">
                <button onClick={() => { onDelete(itemToDelete!); setItemToDelete(null); }} className="w-full py-5 bg-rose-500 text-white font-black rounded-2xl shadow-xl active:scale-95">EXCLUIR AGORA</button>
                <button onClick={() => setItemToDelete(null)} className="w-full py-4 text-slate-400 font-black uppercase text-[10px] tracking-widest">CANCELAR</button>
              </div>
            </div>
          </div>
        </div>
      )}

      {Object.keys(groupedHistory).length === 0 && (
        <div className="text-center py-24 bg-white/50 rounded-[3rem] border-2 border-dashed border-slate-200 mx-1">
          <span className="material-icons text-slate-200 text-6xl mb-4">history_toggle_off</span>
          <p className="text-slate-400 font-bold text-[10px] uppercase tracking-[0.2em]">Nenhum registro encontrado</p>
          {externalFilter && (
            <button onClick={onClearExternalFilter} className="mt-4 text-indigo-600 font-black text-[10px] uppercase border-b border-indigo-200">Limpar filtros</button>
          )}
        </div>
      )}
    </div>
  );
};

export default HistoryList;

import React, { useState, useMemo } from 'react';
import { ServiceRecord } from '../types';
import { WORKERS_LIST } from '../constants';

interface Props { history: ServiceRecord[]; }

const CULTOS = [
  { id: 'SEG', label: 'SEGUNDA', fullName: 'SEGUNDA-FEIRA', roles: ['gate', 'praise'] },
  { id: 'TER', label: 'TERÇA', fullName: 'TERÇA-FEIRA', roles: ['gate', 'praise', 'word'] },
  { id: 'QUA', label: 'QUARTA', fullName: 'QUARTA-FEIRA', roles: ['gate'] },
  { id: 'QUI', label: 'QUINTA', fullName: 'QUINTA-FEIRA', roles: ['gate', 'leader'] },
  { id: 'SÁB', label: 'SÁBADO', fullName: 'SÁBADO', roles: ['gate', 'praise', 'word'] },
  { id: 'EBD', label: 'EBD', fullName: 'EBD', roles: ['gate', 'praise', 'word'] },
  { id: 'DOM', label: 'DOM', fullName: 'DOM', roles: ['gate', 'praise', 'word'] }
];

const WorkerStats: React.FC<Props> = ({ history }) => {
  const [expandedDay, setExpandedDay] = useState<string | null>(null);
  const [expandedRoles, setExpandedRoles] = useState<Record<string, boolean>>({});

  const officialWorkers = useMemo(() => WORKERS_LIST.filter(name => !['VISITANTE', 'TRANSMISSÃO'].includes(name)), []);

  const getStats = (dayFullName: string, role: string) => {
    const today = new Date(); today.setHours(12, 0, 0, 0);
    return officialWorkers.map(name => {
      const filtered = history.filter(r => r.description === dayFullName && r.roles[role as keyof typeof r.roles] === name).sort((a, b) => b.date.localeCompare(a.date));
      const lastDate = filtered[0]?.date || null;
      let daysSince = Infinity;
      if (lastDate) daysSince = Math.ceil((today.getTime() - new Date(lastDate + 'T12:00:00').getTime()) / (1000 * 60 * 60 * 24));
      return { name, lastDate, daysSince };
    }).sort((a, b) => b.daysSince - a.daysSince);
  };

  const toggleRole = (dayId: string, role: string) => {
    const key = `${dayId}-${role}`;
    setExpandedRoles(prev => ({ ...prev, [key]: !prev[key] }));
  };

  const getRoleLabel = (role: string) => {
    switch(role) {
      case 'gate': return 'Portão';
      case 'praise': return 'Louvor';
      case 'word': return 'Palavra';
      case 'leader': return 'Dirigente';
      default: return role;
    }
  };

  const getRoleIcon = (role: string) => {
    switch(role) {
      case 'gate': return 'door_front';
      case 'praise': return 'music_note';
      case 'word': return 'record_voice_over';
      case 'leader': return 'stars';
      default: return 'person';
    }
  };

  return (
    <div className="space-y-6 animate-fadeIn pb-10">
      <div className="px-2">
        <h2 className="text-2xl font-black text-slate-800">Sugestão de Escala</h2>
        <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest mt-1">Quem realizou a função há mais tempo</p>
      </div>

      <div className="grid gap-4">
        {CULTOS.map(culto => (
          <div key={culto.id} className="bg-white rounded-[2rem] border border-slate-100 overflow-hidden shadow-sm">
            <button onClick={() => setExpandedDay(expandedDay === culto.id ? null : culto.id)} className="w-full px-6 py-5 flex items-center justify-between bg-slate-50/50">
              <div className="flex items-center gap-4">
                <div className={`w-10 h-10 rounded-2xl flex items-center justify-center font-black text-[10px] shadow-sm ${expandedDay === culto.id ? 'bg-indigo-600 text-white' : 'bg-white text-slate-400'}`}>{culto.id}</div>
                <span className="font-black text-slate-700 text-sm tracking-wide">{culto.fullName}</span>
              </div>
              <span className={`material-icons text-slate-300 transition-transform ${expandedDay === culto.id ? 'rotate-180' : ''}`}>expand_more</span>
            </button>

            {expandedDay === culto.id && (
              <div className="p-6 space-y-6 animate-fadeIn">
                {culto.roles.map(role => {
                  const isRoleExpanded = expandedRoles[`${culto.id}-${role}`];
                  const stats = getStats(culto.fullName, role);
                  return (
                    <div key={role} className="border border-slate-50 rounded-2xl overflow-hidden">
                      <button onClick={() => toggleRole(culto.id, role)} className="w-full px-4 py-3 flex items-center justify-between bg-white hover:bg-slate-50">
                        <div className="flex items-center gap-2">
                          <span className="material-icons text-indigo-400 text-sm">{getRoleIcon(role)}</span>
                          <span className="font-black text-[10px] text-slate-500 uppercase tracking-widest">{getRoleLabel(role)}</span>
                        </div>
                        <span className={`material-icons text-slate-200 text-sm transition-transform ${isRoleExpanded ? 'rotate-180' : ''}`}>keyboard_arrow_down</span>
                      </button>
                      {isRoleExpanded && (
                        <div className="p-4 bg-slate-50/30 grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 gap-2">
                          {stats.map((worker, i) => (
                            <div key={worker.name} className={`flex items-center justify-between p-3 rounded-xl border ${i === 0 ? 'bg-indigo-50/50 border-indigo-100' : 'bg-white border-transparent'}`}>
                              <span className="text-xs font-bold text-slate-700">{worker.name}</span>
                              <div className="text-right">
                                <span className={`text-[9px] font-black uppercase ${worker.daysSince === Infinity ? 'text-emerald-500' : 'text-indigo-400'}`}>
                                  {worker.daysSince === Infinity ? 'Inédito' : `${worker.daysSince}d`}
                                </span>
                              </div>
                            </div>
                          ))}
                        </div>
                      )}
                    </div>
                  );
                })}
              </div>
            )}
          </div>
        ))}
      </div>
    </div>
  );
};

