      const allAssets = [...CRITICAL_ASSETS, ...EXTERNAL_ASSETS];
      return Promise.allSettled(
        allAssets.map(url => 
          fetch(url, { mode: url.startsWith('http') ? 'cors' : 'no-cors' })
            .then(res => {
              if (res.ok || res.type === 'opaque') return cache.put(url, res);
            })
            .catch(err => console.warn('Cache skip:', url))
        )
      );
    })
  );
  self.skipWaiting();
});

self.addEventListener('activate', (event) => {
  event.waitUntil(
    caches.keys().then((keys) => {
      return Promise.all(
        keys.filter((key) => key !== CACHE_NAME).map((key) => caches.delete(key))
      );
    })
  );
  self.clients.claim();
});

self.addEventListener('fetch', (event) => {
  const { request } = event;
  const url = new URL(request.url);

  // Ignorar requisições Supabase (API em tempo real) e métodos não-GET
  if (request.method !== 'GET' || url.host.includes('supabase.co')) return;

  event.respondWith(
    caches.match(request).then((cachedResponse) => {
      // Se está no cache, retorna imediatamente (estratégia Offline-First)
      if (cachedResponse) return cachedResponse;

      // Se não está no cache, busca na rede e salva para a próxima vez
      return fetch(request).then((networkResponse) => {
        if (networkResponse && networkResponse.status === 200) {
          const cacheCopy = networkResponse.clone();
          caches.open(CACHE_NAME).then((cache) => cache.put(request, cacheCopy));
        }
        return networkResponse;
      }).catch(() => {
        // Fallback: se estiver sem rede e for navegação, entrega o index.html (SPA)
        if (request.mode === 'navigate') {
          return caches.match('index.html');
        }
      });
    })
  );
});

import React from 'react';
import ReactDOM from 'react-dom/client';
import App from './App';

/**
 * Service Worker Registration - Version 16
 * Focuses on extreme resilience for preview environments and iframes.
 */
const registerServiceWorker = async () => {
  if (!('serviceWorker' in navigator)) return;

  // Wait for the document to be fully ready
  if (document.readyState !== 'complete') {
    window.addEventListener('load', () => setTimeout(registerServiceWorker, 1000));
    return;
  }

  try {
    // Only register on secure origins
    const isLocalhost = window.location.hostname === 'localhost' || window.location.hostname === '127.0.0.1';
    const isHttps = window.location.protocol === 'https:';

    if (!isHttps && !isLocalhost) {
      console.warn('Service Worker requer HTTPS ou localhost.');
      return;
    }

    // Attempt registration with a simple relative path
    const registration = await navigator.serviceWorker.register('sw.js', {
      scope: './'
    });

    console.log('Service Worker v16 registrado com sucesso no escopo:', registration.scope);

    registration.onupdatefound = () => {
      const installingWorker = registration.installing;
      if (installingWorker) {
        installingWorker.onstatechange = () => {
          if (installingWorker.state === 'installed' && navigator.serviceWorker.controller) {
            console.log('Nova versão do App disponível. Recarregando...');
            window.location.reload();
          }
        };
      }
    };
  } catch (error: any) {
    // Handle specific documented errors
    if (error.name === 'InvalidStateError') {
      console.warn('Documento em estado inválido para SW. Tentando novamente em 3s...');
      setTimeout(registerServiceWorker, 3000);
    } else if (error.name === 'SecurityError') {
      console.error('Erro de Segurança (Origin Mismatch):', error.message);
    } else {
      console.error('Falha ao registrar Service Worker:', error);
    }
  }
};

// Start registration process
registerServiceWorker();

// Ensure the app reloads when the SW takes control
let refreshing = false;
if ('serviceWorker' in navigator) {
  navigator.serviceWorker.addEventListener('controllerchange', () => {
    if (!refreshing) {
      window.location.reload();
      refreshing = true;
    }
  });
}

