export default App;

import React, { useState, useMemo } from 'react';
import { ServiceRecord } from '../types';
import { WORKERS_LIST } from '../constants';

interface Props {
  history: ServiceRecord[];
  onDelete: (id: string) => void;
  onEdit: (record: ServiceRecord) => void;
  onClearAll: () => void;
  externalFilter?: { worker: string; role: string } | null;
  onClearExternalFilter?: () => void;
}

const HistoryList: React.FC<Props> = ({ 
  history, 
  onDelete, 
  onEdit, 
  externalFilter, 
  onClearExternalFilter 
}) => {
  const [searchTerm, setSearchTerm] = useState('');
  const [itemToDelete, setItemToDelete] = useState<string | null>(null);
  const [isFilterModalOpen, setIsFilterModalOpen] = useState(false);

  // Estados dos Filtros Avançados
  const [filterType, setFilterType] = useState<'ALL' | 'EBD' | 'DOM' | 'WEEKDAY'>('ALL');
  const [filterMonth, setFilterMonth] = useState<string>('ALL');
  const [filterYear, setFilterYear] = useState<string>('ALL');
  const [filterWorker, setFilterWorker] = useState<string>('ALL');
  const [filterRole, setFilterRole] = useState<string>('ALL');

  const monthNames = ["JANEIRO", "FEVEREIRO", "MARÇO", "ABRIL", "MAIO", "JUNHO", "JULHO", "AGOSTO", "SETEMBRO", "OUTUBRO", "NOVEMBRO", "DEZEMBRO"];
  const dayOfWeekNamesShort = ['DOM', 'SEG', 'TER', 'QUA', 'QUI', 'SEX', 'SÁB'];

  const years = useMemo(() => {
    const yrs = history.map(r => r.date.split('-')[0]);
    return [...new Set(yrs)].sort((a, b) => b.localeCompare(a));
  }, [history]);

  const hasActiveFilters = useMemo(() => {
    return filterType !== 'ALL' || filterMonth !== 'ALL' || filterYear !== 'ALL' || filterWorker !== 'ALL' || filterRole !== 'ALL' || !!externalFilter;
  }, [filterType, filterMonth, filterYear, filterWorker, filterRole, externalFilter]);

  const clearAllFilters = () => {
    setFilterType('ALL');
    setFilterMonth('ALL');
    setFilterYear('ALL');
    setFilterWorker('ALL');
    setFilterRole('ALL');
    setSearchTerm('');
    if (onClearExternalFilter) onClearExternalFilter();
  };

  const groupedHistory = useMemo(() => {
    let filtered = [...history];

    // 1. Filtro Externo (vindo do Ranking)
    if (externalFilter) {
      filtered = filtered.filter(r => 
        r.roles[externalFilter.role as keyof typeof r.roles] === externalFilter.worker ||
        (externalFilter.role === 'praise' && r.roles.leader === externalFilter.worker) ||
        (externalFilter.role === 'word' && r.roles.leader === externalFilter.worker)
      );
    }

    // 2. Filtro de Tipo de Culto
    if (filterType !== 'ALL') {
      if (filterType === 'WEEKDAY') {
        filtered = filtered.filter(r => !['EBD', 'DOM'].includes(r.description));
      } else {
        filtered = filtered.filter(r => r.description === filterType);
      }
    }

    // 3. Filtro de Data (Mês/Ano)
    if (filterYear !== 'ALL') {
      filtered = filtered.filter(r => r.date.startsWith(filterYear));
    }
    if (filterMonth !== 'ALL') {
      filtered = filtered.filter(r => {
        const m = (new Date(r.date + 'T12:00:00').getMonth() + 1).toString().padStart(2, '0');
        return m === filterMonth;
      });
    }

    // 4. Filtro de Obreiro e Função Interno
    if (filterWorker !== 'ALL') {
      if (filterRole !== 'ALL') {
        filtered = filtered.filter(r => 
          r.roles[filterRole as keyof typeof r.roles] === filterWorker ||
          (filterRole === 'praise' && r.roles.leader === filterWorker) ||
          (filterRole === 'word' && r.roles.leader === filterWorker)
        );
      } else {
        filtered = filtered.filter(r => 
          Object.values(r.roles).includes(filterWorker)
        );
      }
    }

    // 5. Busca por termo
    if (searchTerm) {
      const lowSearch = searchTerm.toLowerCase();
      filtered = filtered.filter(r => 
        r.date.includes(lowSearch) || 
        r.roles?.word?.toLowerCase().includes(lowSearch) || 
        r.roles?.praise?.toLowerCase().includes(lowSearch) || 
        r.roles?.gate?.toLowerCase().includes(lowSearch) || 
        r.roles?.leader?.toLowerCase().includes(lowSearch) || 
        r.songs.some(s => s.toLowerCase().includes(lowSearch))
      );
    }

    filtered.sort((a, b) => b.date.localeCompare(a.date));

    const groups: Record<string, ServiceRecord[]> = {};
    filtered.forEach(record => {
      const date = new Date(record.date + 'T12:00:00');
      const key = `${monthNames[date.getMonth()]} / ${date.getFullYear()}`;
      if (!groups[key]) groups[key] = [];
      groups[key].push(record);
    });
    return groups;
  }, [history, searchTerm, externalFilter, filterType, filterMonth, filterYear, filterWorker, filterRole]);

  const roleLabels: Record<string, string> = {
    gate: 'PORTÃO',
    praise: 'LOUVOR',
    word: 'PALAVRA',
    leader: 'DIRIGENTE'
  };

  const InfoTag = ({ label, value, icon, roleId }: { label: string, value?: string, icon: string, roleId: string }) => {
    if (!value) return null;

    const isHighlighted = (externalFilter?.role === roleId) || (filterRole === roleId && filterWorker === value);

    return (
      <div className={`flex flex-col border-l-2 pl-3 py-1 transition-all rounded-r-xl ${
        isHighlighted 
          ? 'border-amber-400 bg-amber-50/50 ring-1 ring-amber-100' 
          : 'border-indigo-100'
      }`}>
        <div className="flex items-center gap-1 mb-0.5">
          <span className={`material-icons text-[10px] ${isHighlighted ? 'text-amber-500' : 'text-slate-300'}`}>{icon}</span>
          <span className={`text-[8px] font-black uppercase tracking-widest ${isHighlighted ? 'text-amber-600' : 'text-slate-300'}`}>{label}</span>
        </div>
        <span className={`text-[11px] font-black truncate ${isHighlighted ? 'text-[#1a1c3d]' : 'text-slate-600'}`}>{value}</span>
      </div>
    );
  };

  const formatServiceMessage = (r: ServiceRecord) => {
    const d = new Date(r.date + 'T12:00:00');
    const dayName = d.toLocaleDateString('pt-BR', { weekday: 'long' }).toUpperCase();
    const dateFormatted = d.toLocaleDateString('pt-BR');
    const isWednesday = d.getDay() === 3;
    const isThursday = d.getDay() === 4;

    let msg = `RELATÓRIO DE CULTO\n`;
    msg += `ICM SANTO ANTÔNIO II\n\n`;
    msg += `DATA: ${dateFormatted} (${dayName})\n`;

    if (isWednesday) {
      msg += `*CULTO DIRIGIDO PELO GRUPO DE SENHORAS*\n`;
      if (r.roles.gate) msg += `> Portão: ${r.roles.gate}\n`;
    } else if (isThursday) {
      if (r.roles.gate) msg += `> Portão: ${r.roles.gate}\n`;
      if (r.roles.leader) msg += `> Dirigente: ${r.roles.leader}\n`;
      if (r.roles.scripture) msg += `> Texto: ${r.roles.scripture}\n`;
    } else {
      if (r.roles.gate) msg += `> Portão: ${r.roles.gate}\n`;
      if (r.roles.praise) msg += `> Louvor: ${r.roles.praise}\n`;
      if (r.roles.word) msg += `> Palavra: ${r.roles.word}\n`;
      if (r.roles.scripture) msg += `> Texto: ${r.roles.scripture}\n`;
    }

    if (r.songs && r.songs.length > 0) {
      msg += `Louvores: \n`;
      r.songs.forEach((s) => msg += ` - ${s}\n`);
    }
    return msg;
  };

  const shareMonth = (monthKey: string) => {
    const records = (groupedHistory as Record<string, ServiceRecord[]>)[monthKey];
    if (!records) return;
    let msg = `*RESUMO MENSAL - ${monthKey}*\n\n`;
    records.forEach(r => {
      msg += formatServiceMessage(r);
      msg += `-------------------\n\n`;
    });
    window.open(`https://wa.me/?text=${encodeURIComponent(msg)}`, '_blank');
  };

  return (
    <div className="space-y-8 animate-fadeIn max-w-4xl mx-auto pb-10 px-1">
      <div className="space-y-4">
        <div className="flex items-center gap-2">
          <div className="flex-1 bg-white rounded-full flex items-center px-6 py-4 shadow-xl border border-slate-50">
            <span className="material-icons text-slate-300 mr-3">search</span>
            <input 
              type="text" 
              value={searchTerm} 
              onChange={e => setSearchTerm(e.target.value)} 
              placeholder="Pesquisar histórico..." 
              className="w-full bg-transparent font-bold text-slate-600 outline-none placeholder:text-slate-300" 
            />
          </div>
          <button 
            onClick={() => setIsFilterModalOpen(true)} 
            className={`w-14 h-14 rounded-full flex items-center justify-center shadow-xl shrink-0 active:scale-90 transition-all ${hasActiveFilters ? 'bg-amber-400 text-[#1a1c3d]' : 'bg-indigo-500 text-white'}`}
          >
             <span className="material-icons">{hasActiveFilters ? 'filter_alt' : 'tune'}</span>
          </button>
        </div>

        {hasActiveFilters && (
          <div className="flex flex-wrap items-center gap-2 animate-fadeIn">
            <button 
              onClick={clearAllFilters}
              className="bg-rose-500 text-white px-4 py-2 rounded-full text-[10px] font-black uppercase tracking-widest flex items-center gap-2 shadow-lg active:scale-95"
            >
              <span className="material-icons text-xs">close</span> Limpar Filtros
            </button>
            {filterType !== 'ALL' && (
              <span className="bg-indigo-100 text-indigo-600 px-3 py-2 rounded-full text-[9px] font-black uppercase">{filterType === 'WEEKDAY' ? 'SEMANA' : filterType}</span>
            )}
            {filterWorker !== 'ALL' && (
              <span className="bg-amber-100 text-amber-700 px-3 py-2 rounded-full text-[9px] font-black uppercase">{filterWorker}</span>
            )}
          </div>
        )}
      </div>

      {(Object.entries(groupedHistory) as [string, ServiceRecord[]][]).map(([month, records]) => (
        <div key={month} className="space-y-4">
          <div className="px-4 flex justify-between items-center">
            <h3 className="text-xs font-black text-slate-400 uppercase tracking-[0.3em]">{month}</h3>
            <div className="flex items-center gap-3">
              <span className="text-[10px] font-black text-indigo-300">{records.length} Cultos</span>
              <button onClick={() => shareMonth(month)} className="text-emerald-500 hover:text-emerald-600 transition-colors">
                <span className="material-icons text-sm">share</span>
              </button>
            </div>
          </div>

          <div className="grid gap-4">
            {records.map(record => {
              const d = new Date(record.date + 'T12:00:00');
              const isThursday = d.getDay() === 4;

              return (
                <div key={record.id} className="bg-white rounded-[2.5rem] p-6 md:p-8 shadow-sm border border-slate-100 animate-fadeIn hover:shadow-md transition-shadow">
                  <div className="flex flex-col gap-6">
                    <div className="flex flex-col md:flex-row md:items-center justify-between gap-4">
                      <div className="flex items-center gap-4">
                        <div className="w-12 h-12 bg-slate-50 rounded-2xl flex flex-col items-center justify-center border border-slate-100 shrink-0">
                          <span className="text-[10px] font-black text-indigo-600 leading-none">{d.getDate()}</span>
                          <span className="text-[8px] font-bold text-slate-400 uppercase">{dayOfWeekNamesShort[d.getDay()]}</span>
                        </div>
                        <div className="min-w-0">
                          <h4 className="font-black text-[#1a1c3d] uppercase text-sm tracking-tight truncate">{record.description}</h4>
                          <p className="text-[10px] font-bold text-slate-400 uppercase tracking-widest">{record.songs.length} Louvores</p>
                        </div>
                      </div>

                      <div className="flex items-center gap-2 justify-end">
                        <button onClick={() => window.open(`https://wa.me/?text=${encodeURIComponent(formatServiceMessage(record))}`)} className="w-10 h-10 flex items-center justify-center text-emerald-500 bg-emerald-50/50 rounded-xl active:scale-90"><span className="material-icons text-xl">share</span></button>
                        <button onClick={() => onEdit(record)} className="w-10 h-10 flex items-center justify-center text-indigo-500 bg-indigo-50/50 rounded-xl active:scale-90"><span className="material-icons text-xl">edit</span></button>
                        <button onClick={() => setItemToDelete(record.id)} className="w-10 h-10 flex items-center justify-center text-rose-300 hover:text-rose-500 bg-rose-50/50 rounded-xl active:scale-90"><span className="material-icons text-xl">delete_outline</span></button>
                      </div>
                    </div>

                    <div className={`grid ${isThursday ? 'grid-cols-2 sm:grid-cols-3' : 'grid-cols-2 sm:grid-cols-4'} gap-3 border-t border-slate-50 pt-5`}>
                      <InfoTag label="Portão" value={record.roles.gate} icon="door_front" roleId="gate" />

                      {isThursday ? (
                        <InfoTag label="Dirigente" value={record.roles.leader} icon="stars" roleId="leader" />
                      ) : (
                        <>
                          <InfoTag label="Louvor" value={record.roles.praise} icon="music_note" roleId="praise" />
                          <InfoTag label="Palavra" value={record.roles.word} icon="record_voice_over" roleId="word" />
                        </>
                      )}

                      <InfoTag label="Texto" value={record.roles.word === 'TRANSMISSÃO' ? 'SATÉLITE' : record.roles.scripture} icon="auto_stories" roleId="scripture" />
                    </div>

                    {record.songs.length > 0 && (
                      <div className="pt-4 border-t border-slate-50">
                        <div className="flex flex-wrap gap-2">
                          {record.songs.map((song, idx) => (
                            <div key={idx} className="bg-slate-50 px-3 py-1.5 rounded-lg border border-slate-100 flex items-center gap-2">
                              <span className="text-[8px] font-black text-indigo-300">#{idx + 1}</span>
                              <span className="text-[10px] font-bold text-slate-500 uppercase truncate max-w-[150px]">{song}</span>
                            </div>
                          ))}
                        </div>
                      </div>
                    )}
                  </div>
                </div>
              );
            })}
          </div>
        </div>
      ))}

      {/* Modal de Filtros Avançados */}
      {isFilterModalOpen && (
        <div className="fixed inset-0 z-[8000] flex flex-col justify-end">
          <div className="absolute inset-0 bg-[#1a1c3d]/80 backdrop-blur-sm animate-fadeIn" onClick={() => setIsFilterModalOpen(false)} />
          <div className="relative bg-white rounded-t-[3rem] p-8 max-h-[90vh] flex flex-col shadow-2xl animate-slideUp overflow-hidden">
            <div className="w-12 h-1.5 bg-slate-100 rounded-full mx-auto mb-8 shrink-0"></div>

            <div className="flex justify-between items-center mb-6 shrink-0">
              <h3 className="text-xl font-black text-[#1a1c3d] uppercase tracking-tighter">Filtros Avançados</h3>
              <button onClick={clearAllFilters} className="text-rose-500 font-black text-[9px] uppercase tracking-widest bg-rose-50 px-3 py-1 rounded-full">Limpar Tudo</button>
            </div>

            <div className="flex-1 overflow-y-auto space-y-8 pr-2 custom-scrollbar pb-10">
              {/* Filtro por Tipo */}
              <div className="space-y-3">
                <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest ml-1">Tipo de Culto</label>
                <div className="flex flex-wrap gap-2">
                  {[
                    { id: 'ALL', label: 'Todos' },
                    { id: 'EBD', label: 'EBD' },
                    { id: 'DOM', label: 'Domingo' },
                    { id: 'WEEKDAY', label: 'Semana' }
                  ].map(t => (
                    <button 
                      key={t.id} 
                      onClick={() => setFilterType(t.id as any)}
                      className={`px-5 py-3 rounded-2xl text-[10px] font-black uppercase tracking-widest transition-all ${filterType === t.id ? 'bg-[#1a1c3d] text-white shadow-lg' : 'bg-slate-50 text-slate-400 hover:bg-slate-100'}`}
                    >
                      {t.label}
                    </button>
                  ))}
                </div>
              </div>

              {/* Filtro por Data */}
              <div className="grid grid-cols-2 gap-4">
                <div className="space-y-3">
                  <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest ml-1">Mês</label>
                  <select 
                    value={filterMonth} 
                    onChange={e => setFilterMonth(e.target.value)}
                    className="w-full bg-slate-50 border border-slate-100 rounded-2xl px-4 py-4 font-black text-xs text-[#1a1c3d] outline-none"
                  >
                    <option value="ALL">TODOS</option>
                    {monthNames.map((m, i) => (
                      <option key={m} value={(i + 1).toString().padStart(2, '0')}>{m}</option>
                    ))}
                  </select>
                </div>
                <div className="space-y-3">
                  <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest ml-1">Ano</label>
                  <select 
                    value={filterYear} 
                    onChange={e => setFilterYear(e.target.value)}
                    className="w-full bg-slate-50 border border-slate-100 rounded-2xl px-4 py-4 font-black text-xs text-[#1a1c3d] outline-none"
                  >
                    <option value="ALL">TODOS</option>
                    {years.map(y => <option key={y} value={y}>{y}</option>)}
                  </select>
                </div>
              </div>

              {/* Filtro por Obreiro e Função */}
              <div className="space-y-5 pt-4 border-t border-slate-50">
                <div className="space-y-3">
                  <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest ml-1">Obreiro Específico</label>
                  <select 
                    value={filterWorker} 
                    onChange={e => setFilterWorker(e.target.value)}
                    className="w-full bg-slate-50 border border-slate-100 rounded-2xl px-4 py-4 font-black text-xs text-[#1a1c3d] outline-none"
                  >
                    <option value="ALL">QUALQUER OBREIRO</option>
                    {WORKERS_LIST.map(w => <option key={w} value={w}>{w}</option>)}
                  </select>
                </div>

                <div className="space-y-3">
                  <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest ml-1">Na Função</label>
                  <div className="flex flex-wrap gap-2">
                    {[
                      { id: 'ALL', label: 'Qualquer' },
                      { id: 'gate', label: 'Portão' },
                      { id: 'praise', label: 'Louvor' },
                      { id: 'word', label: 'Palavra' },
                      { id: 'leader', label: 'Dirigente' }
                    ].map(r => (
                      <button 
                        key={r.id} 
                        onClick={() => setFilterRole(r.id)}
                        className={`px-4 py-2.5 rounded-xl text-[9px] font-black uppercase tracking-widest transition-all ${filterRole === r.id ? 'bg-indigo-600 text-white shadow-md' : 'bg-slate-50 text-slate-400 hover:bg-slate-100'}`}
                      >
                        {r.label}
                      </button>
                    ))}
                  </div>
                </div>
              </div>
            </div>

            <div className="p-6 bg-slate-50 border-t border-slate-100 shrink-0">
              <button 
                onClick={() => setIsFilterModalOpen(false)} 
                className="w-full py-5 bg-[#1a1c3d] text-white font-black rounded-3xl uppercase text-[11px] tracking-widest active:scale-95 shadow-xl"
              >
                APLICAR FILTROS
              </button>
            </div>
          </div>
        </div>
      )}

      {itemToDelete && (
        <div className="fixed inset-0 z-[8000] flex flex-col justify-end">
          <div className="absolute inset-0 bg-black/40 backdrop-blur-sm animate-fadeIn" onClick={() => setItemToDelete(null)} />
          <div className="relative bg-white rounded-t-[3rem] p-8 pb-12 shadow-2xl animate-slideUp">
            <div className="w-12 h-1.5 bg-slate-100 rounded-full mx-auto mb-8"></div>
            <div className="flex flex-col items-center text-center">
              <div className="w-16 h-16 bg-rose-50 rounded-full flex items-center justify-center mb-6 text-rose-500">
                <span className="material-icons text-3xl">delete_forever</span>
              </div>
              <h3 className="text-xl font-black text-[#1a1c3d] mb-2 uppercase tracking-tighter">Apagar Registro?</h3>
              <p className="text-slate-400 font-bold text-[10px] uppercase mb-8">Esta ação não pode ser desfeita.</p>
              <div className="w-full flex flex-col gap-3">
                <button onClick={() => { onDelete(itemToDelete!); setItemToDelete(null); }} className="w-full py-5 bg-rose-500 text-white font-black rounded-2xl shadow-xl active:scale-95">EXCLUIR AGORA</button>
                <button onClick={() => setItemToDelete(null)} className="w-full py-4 text-slate-400 font-black uppercase text-[10px] tracking-widest">CANCELAR</button>
              </div>
            </div>
          </div>
        </div>
      )}

      {Object.keys(groupedHistory).length === 0 && (
        <div className="text-center py-24 bg-white/50 rounded-[3rem] border-2 border-dashed border-slate-200 mx-1">
          <span className="material-icons text-slate-200 text-6xl mb-4">history_toggle_off</span>
          <p className="text-slate-400 font-bold text-[10px] uppercase tracking-[0.2em]">Nenhum registro encontrado</p>
          {hasActiveFilters && (
            <button onClick={clearAllFilters} className="mt-4 text-indigo-600 font-black text-[10px] uppercase border-b border-indigo-200">Limpar filtros</button>
          )}
        </div>
      )}
    </div>
  );
};

export default HistoryList;

import React, { useState, useMemo } from 'react';
import { ServiceRecord } from '../types';
import { WORKERS_LIST } from '../constants';

interface Props {
  history: ServiceRecord[];
  onDelete: (id: string) => void;
  onEdit: (record: ServiceRecord) => void;
  onClearAll: () => void;
  externalFilter?: { worker: string; role: string } | null;
  onClearExternalFilter?: () => void;
}

const HistoryList: React.FC<Props> = ({ 
  history, 
  onDelete, 
  onEdit, 
  externalFilter, 
  onClearExternalFilter 
}) => {
  const [searchTerm, setSearchTerm] = useState('');
  const [itemToDelete, setItemToDelete] = useState<string | null>(null);
  const [isFilterModalOpen, setIsFilterModalOpen] = useState(false);

  // Estados dos Filtros Avançados
  const [filterType, setFilterType] = useState<'ALL' | 'EBD' | 'DOM' | 'WEEKDAY'>('ALL');
  const [filterMonth, setFilterMonth] = useState<string>('ALL');
  const [filterYear, setFilterYear] = useState<string>('ALL');
  const [filterWorker, setFilterWorker] = useState<string>('ALL');
  const [filterRole, setFilterRole] = useState<string>('ALL');

  const monthNames = ["JANEIRO", "FEVEREIRO", "MARÇO", "ABRIL", "MAIO", "JUNHO", "JULHO", "AGOSTO", "SETEMBRO", "OUTUBRO", "NOVEMBRO", "DEZEMBRO"];
  const dayOfWeekNamesShort = ['DOM', 'SEG', 'TER', 'QUA', 'QUI', 'SEX', 'SÁB'];

  const years = useMemo(() => {
    const yrs = history.map(r => r.date.split('-')[0]);
    // Fix: Explicitly cast to string[] to avoid 'unknown' type error on localeCompare
    return ([...new Set(yrs)] as string[]).sort((a, b) => b.localeCompare(a));
  }, [history]);

  const hasActiveFilters = useMemo(() => {
    return filterType !== 'ALL' || filterMonth !== 'ALL' || filterYear !== 'ALL' || filterWorker !== 'ALL' || filterRole !== 'ALL' || !!externalFilter;
  }, [filterType, filterMonth, filterYear, filterWorker, filterRole, externalFilter]);

  const clearAllFilters = () => {
    setFilterType('ALL');
    setFilterMonth('ALL');
    setFilterYear('ALL');
    setFilterWorker('ALL');
    setFilterRole('ALL');
    setSearchTerm('');
    if (onClearExternalFilter) onClearExternalFilter();
  };

  const groupedHistory = useMemo(() => {
    let filtered = [...history];

    // 1. Filtro Externo (vindo do Ranking)
    if (externalFilter) {
      filtered = filtered.filter(r => 
        r.roles[externalFilter.role as keyof typeof r.roles] === externalFilter.worker ||
        (externalFilter.role === 'praise' && r.roles.leader === externalFilter.worker) ||
        (externalFilter.role === 'word' && r.roles.leader === externalFilter.worker)
      );
    }

    // 2. Filtro de Tipo de Culto
    if (filterType !== 'ALL') {
      if (filterType === 'WEEKDAY') {
        filtered = filtered.filter(r => !['EBD', 'DOM'].includes(r.description));
      } else {
        filtered = filtered.filter(r => r.description === filterType);
      }
    }

    // 3. Filtro de Data (Mês/Ano)
    if (filterYear !== 'ALL') {
      filtered = filtered.filter(r => r.date.startsWith(filterYear));
    }
    if (filterMonth !== 'ALL') {
      filtered = filtered.filter(r => {
        const m = (new Date(r.date + 'T12:00:00').getMonth() + 1).toString().padStart(2, '0');
        return m === filterMonth;
      });
    }

    // 4. Filtro de Obreiro e Função Interno
    if (filterWorker !== 'ALL') {
      if (filterRole !== 'ALL') {
        filtered = filtered.filter(r => 
          r.roles[filterRole as keyof typeof r.roles] === filterWorker ||
          (filterRole === 'praise' && r.roles.leader === filterWorker) ||
          (filterRole === 'word' && r.roles.leader === filterWorker)
        );
      } else {
        filtered = filtered.filter(r => 
          Object.values(r.roles).includes(filterWorker)
        );
      }
    }

    // 5. Busca por termo
    if (searchTerm) {
      const lowSearch = searchTerm.toLowerCase();
      filtered = filtered.filter(r => 
        r.date.includes(lowSearch) || 
        r.roles?.word?.toLowerCase().includes(lowSearch) || 
        r.roles?.praise?.toLowerCase().includes(lowSearch) || 
        r.roles?.gate?.toLowerCase().includes(lowSearch) || 
        r.roles?.leader?.toLowerCase().includes(lowSearch) || 
        r.songs.some(s => s.toLowerCase().includes(lowSearch))
      );
    }

    filtered.sort((a, b) => b.date.localeCompare(a.date));

    const groups: Record<string, ServiceRecord[]> = {};
    filtered.forEach(record => {
      const date = new Date(record.date + 'T12:00:00');
      const key = `${monthNames[date.getMonth()]} / ${date.getFullYear()}`;
      if (!groups[key]) groups[key] = [];
      groups[key].push(record);
    });
    return groups;
  }, [history, searchTerm, externalFilter, filterType, filterMonth, filterYear, filterWorker, filterRole]);

  const roleLabels: Record<string, string> = {
    gate: 'PORTÃO',
    praise: 'LOUVOR',
    word: 'PALAVRA',
    leader: 'DIRIGENTE'
  };

  const InfoTag = ({ label, value, icon, roleId }: { label: string, value?: string, icon: string, roleId: string }) => {
    if (!value) return null;

    const isHighlighted = (externalFilter?.role === roleId) || (filterRole === roleId && filterWorker === value);

    return (
      <div className={`flex flex-col border-l-2 pl-3 py-1 transition-all rounded-r-xl ${
        isHighlighted 
          ? 'border-amber-400 bg-amber-50/50 ring-1 ring-amber-100' 
          : 'border-indigo-100'
      }`}>
        <div className="flex items-center gap-1 mb-0.5">
          <span className={`material-icons text-[10px] ${isHighlighted ? 'text-amber-500' : 'text-slate-300'}`}>{icon}</span>
          <span className={`text-[8px] font-black uppercase tracking-widest ${isHighlighted ? 'text-amber-600' : 'text-slate-300'}`}>{label}</span>
        </div>
        <span className={`text-[11px] font-black truncate ${isHighlighted ? 'text-[#1a1c3d]' : 'text-slate-600'}`}>{value}</span>
      </div>
    );
  };

  const formatServiceMessage = (r: ServiceRecord) => {
    const d = new Date(r.date + 'T12:00:00');
    const dayName = d.toLocaleDateString('pt-BR', { weekday: 'long' }).toUpperCase();
    const dateFormatted = d.toLocaleDateString('pt-BR');
    const isWednesday = d.getDay() === 3;
    const isThursday = d.getDay() === 4;

    let msg = `RELATÓRIO DE CULTO\n`;
    msg += `ICM SANTO ANTÔNIO II\n\n`;
    msg += `DATA: ${dateFormatted} (${dayName})\n`;

    if (isWednesday) {
      msg += `*CULTO DIRIGIDO PELO GRUPO DE SENHORAS*\n`;
      if (r.roles.gate) msg += `> Portão: ${r.roles.gate}\n`;
    } else if (isThursday) {
      if (r.roles.gate) msg += `> Portão: ${r.roles.gate}\n`;
      if (r.roles.leader) msg += `> Dirigente: ${r.roles.leader}\n`;
      if (r.roles.scripture) msg += `> Texto: ${r.roles.scripture}\n`;
    } else {
      if (r.roles.gate) msg += `> Portão: ${r.roles.gate}\n`;
      if (r.roles.praise) msg += `> Louvor: ${r.roles.praise}\n`;
      if (r.roles.word) msg += `> Palavra: ${r.roles.word}\n`;
      if (r.roles.scripture) msg += `> Texto: ${r.roles.scripture}\n`;
    }

    if (r.songs && r.songs.length > 0) {
      msg += `Louvores: \n`;
      r.songs.forEach((s) => msg += ` - ${s}\n`);
    }
    return msg;
  };

  const shareMonth = (monthKey: string) => {
    const records = (groupedHistory as Record<string, ServiceRecord[]>)[monthKey];
    if (!records) return;
    let msg = `*RESUMO MENSAL - ${monthKey}*\n\n`;
    records.forEach(r => {
      msg += formatServiceMessage(r);
      msg += `-------------------\n\n`;
    });
    window.open(`https://wa.me/?text=${encodeURIComponent(msg)}`, '_blank');
  };

  return (
    <div className="space-y-8 animate-fadeIn max-w-4xl mx-auto pb-10 px-1">
      <div className="space-y-4">
        <div className="flex items-center gap-2">
          <div className="flex-1 bg-white rounded-full flex items-center px-6 py-4 shadow-xl border border-slate-50">
            <span className="material-icons text-slate-300 mr-3">search</span>
            <input 
              type="text" 
              value={searchTerm} 
              onChange={e => setSearchTerm(e.target.value)} 
              placeholder="Pesquisar histórico..." 
              className="w-full bg-transparent font-bold text-slate-600 outline-none placeholder:text-slate-300" 
            />
          </div>
          <button 
            onClick={() => setIsFilterModalOpen(true)} 
            className={`w-14 h-14 rounded-full flex items-center justify-center shadow-xl shrink-0 active:scale-90 transition-all ${hasActiveFilters ? 'bg-amber-400 text-[#1a1c3d]' : 'bg-indigo-500 text-white'}`}
          >
             <span className="material-icons">{hasActiveFilters ? 'filter_alt' : 'tune'}</span>
          </button>
        </div>

        {hasActiveFilters && (
          <div className="flex flex-wrap items-center gap-2 animate-fadeIn">
            <button 
              onClick={clearAllFilters}
              className="bg-rose-500 text-white px-4 py-2 rounded-full text-[10px] font-black uppercase tracking-widest flex items-center gap-2 shadow-lg active:scale-95"
            >
              <span className="material-icons text-xs">close</span> Limpar Filtros
            </button>
            {filterType !== 'ALL' && (
              <span className="bg-indigo-100 text-indigo-600 px-3 py-2 rounded-full text-[9px] font-black uppercase">{filterType === 'WEEKDAY' ? 'SEMANA' : filterType}</span>
            )}
            {filterWorker !== 'ALL' && (
              <span className="bg-amber-100 text-amber-700 px-3 py-2 rounded-full text-[9px] font-black uppercase">{filterWorker}</span>
            )}
          </div>
        )}
      </div>

      {(Object.entries(groupedHistory) as [string, ServiceRecord[]][]).map(([month, records]) => (
        <div key={month} className="space-y-4">
          <div className="px-4 flex justify-between items-center">
            <h3 className="text-xs font-black text-slate-400 uppercase tracking-[0.3em]">{month}</h3>
            <div className="flex items-center gap-3">
              <span className="text-[10px] font-black text-indigo-300">{records.length} Cultos</span>
              <button onClick={() => shareMonth(month)} className="text-emerald-500 hover:text-emerald-600 transition-colors">
                <span className="material-icons text-sm">share</span>
              </button>
            </div>
          </div>

          <div className="grid gap-4">
            {records.map(record => {
              const d = new Date(record.date + 'T12:00:00');
              const isThursday = d.getDay() === 4;

              return (
                <div key={record.id} className="bg-white rounded-[2.5rem] p-6 md:p-8 shadow-sm border border-slate-100 animate-fadeIn hover:shadow-md transition-shadow">
                  <div className="flex flex-col gap-6">
                    <div className="flex flex-col md:flex-row md:items-center justify-between gap-4">
                      <div className="flex items-center gap-4">
                        <div className="w-12 h-12 bg-slate-50 rounded-2xl flex flex-col items-center justify-center border border-slate-100 shrink-0">
                          <span className="text-[10px] font-black text-indigo-600 leading-none">{d.getDate()}</span>
                          <span className="text-[8px] font-bold text-slate-400 uppercase">{dayOfWeekNamesShort[d.getDay()]}</span>
                        </div>
                        <div className="min-w-0">
                          <h4 className="font-black text-[#1a1c3d] uppercase text-sm tracking-tight truncate">{record.description}</h4>
                          <p className="text-[10px] font-bold text-slate-400 uppercase tracking-widest">{record.songs.length} Louvores</p>
                        </div>
                      </div>

                      <div className="flex items-center gap-2 justify-end">
                        <button onClick={() => window.open(`https://wa.me/?text=${encodeURIComponent(formatServiceMessage(record))}`)} className="w-10 h-10 flex items-center justify-center text-emerald-500 bg-emerald-50/50 rounded-xl active:scale-90"><span className="material-icons text-xl">share</span></button>
                        <button onClick={() => onEdit(record)} className="w-10 h-10 flex items-center justify-center text-indigo-500 bg-indigo-50/50 rounded-xl active:scale-90"><span className="material-icons text-xl">edit</span></button>
                        <button onClick={() => setItemToDelete(record.id)} className="w-10 h-10 flex items-center justify-center text-rose-300 hover:text-rose-500 bg-rose-50/50 rounded-xl active:scale-90"><span className="material-icons text-xl">delete_outline</span></button>
                      </div>
                    </div>

                    <div className={`grid ${isThursday ? 'grid-cols-2 sm:grid-cols-3' : 'grid-cols-2 sm:grid-cols-4'} gap-3 border-t border-slate-50 pt-5`}>
                      <InfoTag label="Portão" value={record.roles.gate} icon="door_front" roleId="gate" />

                      {isThursday ? (
                        <InfoTag label="Dirigente" value={record.roles.leader} icon="stars" roleId="leader" />
                      ) : (
                        <>
                          <InfoTag label="Louvor" value={record.roles.praise} icon="music_note" roleId="praise" />
                          <InfoTag label="Palavra" value={record.roles.word} icon="record_voice_over" roleId="word" />
                        </>
                      )}

                      <InfoTag label="Texto" value={record.roles.word === 'TRANSMISSÃO' ? 'SATÉLITE' : record.roles.scripture} icon="auto_stories" roleId="scripture" />
                    </div>

                    {record.songs.length > 0 && (
                      <div className="pt-4 border-t border-slate-50">
                        <div className="flex flex-wrap gap-2">
                          {record.songs.map((song, idx) => (
                            <div key={idx} className="bg-slate-50 px-3 py-1.5 rounded-lg border border-slate-100 flex items-center gap-2">
                              <span className="text-[8px] font-black text-indigo-300">#{idx + 1}</span>
                              <span className="text-[10px] font-bold text-slate-500 uppercase truncate max-w-[150px]">{song}</span>
                            </div>
                          ))}
                        </div>
                      </div>
                    )}
                  </div>
                </div>
              );
            })}
          </div>
        </div>
      ))}

      {/* Modal de Filtros Avançados */}
      {isFilterModalOpen && (
        <div className="fixed inset-0 z-[8000] flex flex-col justify-end">
          <div className="absolute inset-0 bg-[#1a1c3d]/80 backdrop-blur-sm animate-fadeIn" onClick={() => setIsFilterModalOpen(false)} />
          <div className="relative bg-white rounded-t-[3rem] p-8 max-h-[90vh] flex flex-col shadow-2xl animate-slideUp overflow-hidden">
            <div className="w-12 h-1.5 bg-slate-100 rounded-full mx-auto mb-8 shrink-0"></div>

            <div className="flex justify-between items-center mb-6 shrink-0">
              <h3 className="text-xl font-black text-[#1a1c3d] uppercase tracking-tighter">Filtros Avançados</h3>
              <button onClick={clearAllFilters} className="text-rose-500 font-black text-[9px] uppercase tracking-widest bg-rose-50 px-3 py-1 rounded-full">Limpar Tudo</button>
            </div>

            <div className="flex-1 overflow-y-auto space-y-8 pr-2 custom-scrollbar pb-10">
              {/* Filtro por Tipo */}
              <div className="space-y-3">
                <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest ml-1">Tipo de Culto</label>
                <div className="flex flex-wrap gap-2">
                  {[
                    { id: 'ALL', label: 'Todos' },
                    { id: 'EBD', label: 'EBD' },
                    { id: 'DOM', label: 'Domingo' },
                    { id: 'WEEKDAY', label: 'Semana' }
                  ].map(t => (
                    <button 
                      key={t.id} 
                      onClick={() => setFilterType(t.id as any)}
                      className={`px-5 py-3 rounded-2xl text-[10px] font-black uppercase tracking-widest transition-all ${filterType === t.id ? 'bg-[#1a1c3d] text-white shadow-lg' : 'bg-slate-50 text-slate-400 hover:bg-slate-100'}`}
                    >
                      {t.label}
                    </button>
                  ))}
                </div>
              </div>

              {/* Filtro por Data */}
              <div className="grid grid-cols-2 gap-4">
                <div className="space-y-3">
                  <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest ml-1">Mês</label>
                  <select 
                    value={filterMonth} 
                    onChange={e => setFilterMonth(e.target.value)}
                    className="w-full bg-slate-50 border border-slate-100 rounded-2xl px-4 py-4 font-black text-xs text-[#1a1c3d] outline-none"
                  >
                    <option value="ALL">TODOS</option>
                    {monthNames.map((m, i) => (
                      <option key={m} value={(i + 1).toString().padStart(2, '0')}>{m}</option>
                    ))}
                  </select>
                </div>
                <div className="space-y-3">
                  <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest ml-1">Ano</label>
                  <select 
                    value={filterYear} 
                    onChange={e => setFilterYear(e.target.value)}
                    className="w-full bg-slate-50 border border-slate-100 rounded-2xl px-4 py-4 font-black text-xs text-[#1a1c3d] outline-none"
                  >
                    <option value="ALL">TODOS</option>
                    {years.map(y => <option key={y} value={y}>{y}</option>)}
                  </select>
                </div>
              </div>

              {/* Filtro por Obreiro e Função */}
              <div className="space-y-5 pt-4 border-t border-slate-50">
                <div className="space-y-3">
                  <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest ml-1">Obreiro Específico</label>
                  <select 
                    value={filterWorker} 
                    onChange={e => setFilterWorker(e.target.value)}
                    className="w-full bg-slate-50 border border-slate-100 rounded-2xl px-4 py-4 font-black text-xs text-[#1a1c3d] outline-none"
                  >
                    <option value="ALL">QUALQUER OBREIRO</option>
                    {WORKERS_LIST.map(w => <option key={w} value={w}>{w}</option>)}
                  </select>
                </div>

                <div className="space-y-3">
                  <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest ml-1">Na Função</label>
                  <div className="flex flex-wrap gap-2">
                    {[
                      { id: 'ALL', label: 'Qualquer' },
                      { id: 'gate', label: 'Portão' },
                      { id: 'praise', label: 'Louvor' },
                      { id: 'word', label: 'Palavra' },
                      { id: 'leader', label: 'Dirigente' }
                    ].map(r => (
                      <button 
                        key={r.id} 
                        onClick={() => setFilterRole(r.id)}
                        className={`px-4 py-2.5 rounded-xl text-[9px] font-black uppercase tracking-widest transition-all ${filterRole === r.id ? 'bg-indigo-600 text-white shadow-md' : 'bg-slate-50 text-slate-400 hover:bg-slate-100'}`}
                      >
                        {r.label}
                      </button>
                    ))}
                  </div>
                </div>
              </div>
            </div>

            <div className="p-6 bg-slate-50 border-t border-slate-100 shrink-0">
              <button 
                onClick={() => setIsFilterModalOpen(false)} 
                className="w-full py-5 bg-[#1a1c3d] text-white font-black rounded-3xl uppercase text-[11px] tracking-widest active:scale-95 shadow-xl"
              >
                APLICAR FILTROS
              </button>
            </div>
          </div>
        </div>
      )}

      {itemToDelete && (
        <div className="fixed inset-0 z-[8000] flex flex-col justify-end">
          <div className="absolute inset-0 bg-black/40 backdrop-blur-sm animate-fadeIn" onClick={() => setItemToDelete(null)} />
          <div className="relative bg-white rounded-t-[3rem] p-8 pb-12 shadow-2xl animate-slideUp">
            <div className="w-12 h-1.5 bg-slate-100 rounded-full mx-auto mb-8"></div>
            <div className="flex flex-col items-center text-center">
              <div className="w-16 h-16 bg-rose-50 rounded-full flex items-center justify-center mb-6 text-rose-500">
                <span className="material-icons text-3xl">delete_forever</span>
              </div>
              <h3 className="text-xl font-black text-[#1a1c3d] mb-2 uppercase tracking-tighter">Apagar Registro?</h3>
              <p className="text-slate-400 font-bold text-[10px] uppercase mb-8">Esta ação não pode ser desfeita.</p>
              <div className="w-full flex flex-col gap-3">
                <button onClick={() => { onDelete(itemToDelete!); setItemToDelete(null); }} className="w-full py-5 bg-rose-500 text-white font-black rounded-2xl shadow-xl active:scale-95">EXCLUIR AGORA</button>
                <button onClick={() => setItemToDelete(null)} className="w-full py-4 text-slate-400 font-black uppercase text-[10px] tracking-widest">CANCELAR</button>
              </div>
            </div>
          </div>
        </div>
      )}

      {Object.keys(groupedHistory).length === 0 && (
        <div className="text-center py-24 bg-white/50 rounded-[3rem] border-2 border-dashed border-slate-200 mx-1">
          <span className="material-icons text-slate-200 text-6xl mb-4">history_toggle_off</span>
          <p className="text-slate-400 font-bold text-[10px] uppercase tracking-[0.2em]">Nenhum registro encontrado</p>
          {hasActiveFilters && (
            <button onClick={clearAllFilters} className="mt-4 text-indigo-600 font-black text-[10px] uppercase border-b border-indigo-200">Limpar filtros</button>
          )}
        </div>
      )}
    </div>
  );
};

export default HistoryList;

import React, { useState, useMemo } from 'react';
import { ServiceRecord } from '../types';
import { WORKERS_LIST } from '../constants';

interface Props {
  history: ServiceRecord[];
  onDelete: (id: string) => void;
  onEdit: (record: ServiceRecord) => void;
  onClearAll: () => void;
  externalFilter?: { worker: string; role: string } | null;
  onClearExternalFilter?: () => void;
}

const HistoryList: React.FC<Props> = ({ 
  history, 
  onDelete, 
  onEdit, 
  externalFilter, 
  onClearExternalFilter 
}) => {
  const [searchTerm, setSearchTerm] = useState('');
  const [itemToDelete, setItemToDelete] = useState<string | null>(null);
  const [isFilterModalOpen, setIsFilterModalOpen] = useState(false);

  // Estados dos Filtros Avançados
  const [filterType, setFilterType] = useState<'ALL' | 'EBD' | 'DOM' | 'WEEKDAY'>('ALL');
  const [filterMonth, setFilterMonth] = useState<string>('ALL');
  const [filterYear, setFilterYear] = useState<string>('ALL');
  const [filterWorker, setFilterWorker] = useState<string>('ALL');
  const [filterRole, setFilterRole] = useState<string>('ALL');

  const monthNames = ["JANEIRO", "FEVEREIRO", "MARÇO", "ABRIL", "MAIO", "JUNHO", "JULHO", "AGOSTO", "SETEMBRO", "OUTUBRO", "NOVEMBRO", "DEZEMBRO"];
  const dayOfWeekNamesShort = ['DOM', 'SEG', 'TER', 'QUA', 'QUI', 'SEX', 'SÁB'];

  const years = useMemo(() => {
    const yrs = history.map(r => r.date.split('-')[0]);
    return ([...new Set(yrs)] as string[]).sort((a, b) => b.localeCompare(a));
  }, [history]);

  const hasActiveFilters = useMemo(() => {
    return filterType !== 'ALL' || filterMonth !== 'ALL' || filterYear !== 'ALL' || filterWorker !== 'ALL' || filterRole !== 'ALL' || !!externalFilter;
  }, [filterType, filterMonth, filterYear, filterWorker, filterRole, externalFilter]);

  const clearAllFilters = () => {
    setFilterType('ALL');
    setFilterMonth('ALL');
    setFilterYear('ALL');
    setFilterWorker('ALL');
    setFilterRole('ALL');
    setSearchTerm('');
    if (onClearExternalFilter) onClearExternalFilter();
  };

  const groupedHistory = useMemo(() => {
    let filtered = [...history];

    if (externalFilter) {
      filtered = filtered.filter(r => 
        r.roles[externalFilter.role as keyof typeof r.roles] === externalFilter.worker ||
        (externalFilter.role === 'praise' && r.roles.leader === externalFilter.worker) ||
        (externalFilter.role === 'word' && r.roles.leader === externalFilter.worker)
      );
    }

    if (filterType !== 'ALL') {
      if (filterType === 'WEEKDAY') {
        filtered = filtered.filter(r => !['EBD', 'DOM'].includes(r.description));
      } else {
        filtered = filtered.filter(r => r.description === filterType);
      }
    }

    if (filterYear !== 'ALL') {
      filtered = filtered.filter(r => r.date.startsWith(filterYear));
    }
    if (filterMonth !== 'ALL') {
      filtered = filtered.filter(r => {
        const m = (new Date(r.date + 'T12:00:00').getMonth() + 1).toString().padStart(2, '0');
        return m === filterMonth;
      });
    }

    if (filterWorker !== 'ALL') {
      if (filterRole !== 'ALL') {
        filtered = filtered.filter(r => 
          r.roles[filterRole as keyof typeof r.roles] === filterWorker ||
          (filterRole === 'praise' && r.roles.leader === filterWorker) ||
          (filterRole === 'word' && r.roles.leader === filterWorker)
        );
      } else {
        filtered = filtered.filter(r => 
          Object.values(r.roles).includes(filterWorker)
        );
      }
    }

    if (searchTerm) {
      const lowSearch = searchTerm.toLowerCase();
      filtered = filtered.filter(r => 
        r.date.includes(lowSearch) || 
        r.roles?.word?.toLowerCase().includes(lowSearch) || 
        r.roles?.praise?.toLowerCase().includes(lowSearch) || 
        r.roles?.gate?.toLowerCase().includes(lowSearch) || 
        r.roles?.leader?.toLowerCase().includes(lowSearch) || 
        r.songs.some(s => s.toLowerCase().includes(lowSearch))
      );
    }

    filtered.sort((a, b) => b.date.localeCompare(a.date));

    const groups: Record<string, ServiceRecord[]> = {};
    filtered.forEach(record => {
      const date = new Date(record.date + 'T12:00:00');
      const key = `${monthNames[date.getMonth()]} / ${date.getFullYear()}`;
      if (!groups[key]) groups[key] = [];
      groups[key].push(record);
    });
    return groups;
  }, [history, searchTerm, externalFilter, filterType, filterMonth, filterYear, filterWorker, filterRole]);

  const InfoTag = ({ label, value, icon, roleId }: { label: string, value?: string, icon: string, roleId: string }) => {
    if (!value) return null;

    const isHighlighted = (externalFilter?.role === roleId) || (filterRole === roleId && filterWorker === value);

    return (
      <div className={`flex items-center gap-3 p-3 rounded-2xl transition-all ${
        isHighlighted 
          ? 'bg-amber-400/10 ring-1 ring-amber-400/20' 
          : 'bg-slate-50 border border-slate-100/50'
      }`}>
        <div className={`w-9 h-9 rounded-xl flex items-center justify-center shrink-0 ${
          isHighlighted ? 'bg-amber-400 text-amber-900' : 'bg-white text-slate-400 border border-slate-100'
        }`}>
          <span className="material-icons text-[18px]">{icon}</span>
        </div>
        <div className="flex flex-col min-w-0">
          <span className={`text-[8px] font-black uppercase tracking-widest ${isHighlighted ? 'text-amber-600' : 'text-slate-400'}`}>
            {label}
          </span>
          <span className={`text-[11px] font-black truncate ${isHighlighted ? 'text-[#1a1c3d]' : 'text-slate-700'}`}>
            {value}
          </span>
        </div>
      </div>
    );
  };

  const formatServiceMessage = (r: ServiceRecord) => {
    const d = new Date(r.date + 'T12:00:00');
    const dayName = d.toLocaleDateString('pt-BR', { weekday: 'long' }).toUpperCase();
    const dateFormatted = d.toLocaleDateString('pt-BR');
    const isWednesday = d.getDay() === 3;
    const isThursday = d.getDay() === 4;

    let msg = `RELATÓRIO DE CULTO\n`;
    msg += `ICM SANTO ANTÔNIO II\n\n`;
    msg += `DATA: ${dateFormatted} (${dayName})\n`;

    if (isWednesday) {
      msg += `*CULTO DIRIGIDO PELO GRUPO DE SENHORAS*\n`;
      if (r.roles.gate) msg += `> Portão: ${r.roles.gate}\n`;
    } else if (isThursday) {
      if (r.roles.gate) msg += `> Portão: ${r.roles.gate}\n`;
      if (r.roles.leader) msg += `> Dirigente: ${r.roles.leader}\n`;
      if (r.roles.scripture) msg += `> Texto: ${r.roles.scripture}\n`;
    } else {
      if (r.roles.gate) msg += `> Portão: ${r.roles.gate}\n`;
      if (r.roles.praise) msg += `> Louvor: ${r.roles.praise}\n`;
      if (r.roles.word) msg += `> Palavra: ${r.roles.word}\n`;
      if (r.roles.scripture) msg += `> Texto: ${r.roles.scripture}\n`;
    }

    if (r.songs && r.songs.length > 0) {
      msg += `Louvores: \n`;
      r.songs.forEach((s) => msg += ` - ${s}\n`);
    }
    return msg;
  };

  const shareMonth = (monthKey: string) => {
    const records = (groupedHistory as Record<string, ServiceRecord[]>)[monthKey];
    if (!records) return;
    let msg = `*RESUMO MENSAL - ${monthKey}*\n\n`;
    records.forEach(r => {
      msg += formatServiceMessage(r);
      msg += `-------------------\n\n`;
    });
    window.open(`https://wa.me/?text=${encodeURIComponent(msg)}`, '_blank');
  };

  return (
    <div className="space-y-8 animate-fadeIn max-w-4xl mx-auto pb-10 px-1">
      <div className="space-y-4">
        <div className="flex items-center gap-2">
          <div className="flex-1 bg-white rounded-full flex items-center px-6 py-4 shadow-xl border border-slate-50">
            <span className="material-icons text-slate-300 mr-3">search</span>
            <input 
              type="text" 
              value={searchTerm} 
              onChange={e => setSearchTerm(e.target.value)} 
              placeholder="Pesquisar histórico..." 
              className="w-full bg-transparent font-bold text-slate-600 outline-none placeholder:text-slate-300" 
            />
          </div>
          <button 
            onClick={() => setIsFilterModalOpen(true)} 
            className={`w-14 h-14 rounded-full flex items-center justify-center shadow-xl shrink-0 active:scale-90 transition-all ${hasActiveFilters ? 'bg-amber-400 text-[#1a1c3d]' : 'bg-indigo-500 text-white'}`}
          >
             <span className="material-icons">{hasActiveFilters ? 'filter_alt' : 'tune'}</span>
          </button>
        </div>

        {hasActiveFilters && (
          <div className="flex flex-wrap items-center gap-2 animate-fadeIn">
            <button 
              onClick={clearAllFilters}
              className="bg-rose-500 text-white px-4 py-2 rounded-full text-[10px] font-black uppercase tracking-widest flex items-center gap-2 shadow-lg active:scale-95"
            >
              <span className="material-icons text-xs">close</span> Limpar Filtros
            </button>
            {filterType !== 'ALL' && (
              <span className="bg-indigo-100 text-indigo-600 px-3 py-2 rounded-full text-[9px] font-black uppercase">{filterType === 'WEEKDAY' ? 'SEMANA' : filterType}</span>
            )}
            {filterWorker !== 'ALL' && (
              <span className="bg-amber-100 text-amber-700 px-3 py-2 rounded-full text-[9px] font-black uppercase">{filterWorker}</span>
            )}
          </div>
        )}
      </div>

      {(Object.entries(groupedHistory) as [string, ServiceRecord[]][]).map(([month, records]) => (
        <div key={month} className="space-y-4">
          <div className="px-4 flex justify-between items-center">
            <h3 className="text-xs font-black text-slate-400 uppercase tracking-[0.3em]">{month}</h3>
            <div className="flex items-center gap-3">
              <span className="text-[10px] font-black text-indigo-300">{records.length} Cultos</span>
              <button onClick={() => shareMonth(month)} className="text-emerald-500 hover:text-emerald-600 transition-colors">
                <span className="material-icons text-sm">share</span>
              </button>
            </div>
          </div>

          <div className="grid gap-6">
            {records.map(record => {
              const d = new Date(record.date + 'T12:00:00');
              const isThursday = d.getDay() === 4;
              const isWednesday = d.getDay() === 3;

              return (
                <div key={record.id} className="bg-white rounded-[3rem] shadow-sm border border-slate-100 animate-fadeIn hover:shadow-md transition-shadow overflow-hidden flex flex-col">
                  {/* Header do Card */}
                  <div className="p-6 md:p-8 flex flex-col md:flex-row md:items-center justify-between gap-6 bg-slate-50/50 border-b border-slate-100">
                    <div className="flex items-center gap-5">
                      <div className="w-14 h-14 bg-white rounded-2xl flex flex-col items-center justify-center border border-slate-200 shadow-sm shrink-0">
                        <span className="text-lg font-black text-[#1a1c3d] leading-none">{d.getDate()}</span>
                        <span className="text-[9px] font-black text-indigo-500 uppercase mt-0.5">{dayOfWeekNamesShort[d.getDay()]}</span>
                      </div>
                      <div className="min-w-0">
                        <div className="flex items-center gap-2 mb-1">
                          <span className={`text-[8px] font-black px-2 py-0.5 rounded-full uppercase tracking-widest ${
                            record.description === 'EBD' ? 'bg-amber-100 text-amber-700' : 
                            record.description === 'DOM' ? 'bg-indigo-100 text-indigo-700' : 
                            'bg-slate-200 text-slate-600'
                          }`}>
                            {record.description}
                          </span>
                        </div>
                        <h4 className="font-black text-[#1a1c3d] uppercase text-sm tracking-tight truncate">
                          Culto de {dayOfWeekNamesShort[d.getDay()]} - ICM Santo Antônio II
                        </h4>
                      </div>
                    </div>

                    <div className="flex items-center gap-2 justify-end">
                      <button onClick={() => window.open(`https://wa.me/?text=${encodeURIComponent(formatServiceMessage(record))}`)} className="w-11 h-11 flex items-center justify-center text-emerald-500 bg-white border border-emerald-100 rounded-2xl shadow-sm active:scale-90 transition-all"><span className="material-icons text-xl">share</span></button>
                      <button onClick={() => onEdit(record)} className="w-11 h-11 flex items-center justify-center text-indigo-500 bg-white border border-indigo-100 rounded-2xl shadow-sm active:scale-90 transition-all"><span className="material-icons text-xl">edit</span></button>
                      <button onClick={() => setItemToDelete(record.id)} className="w-11 h-11 flex items-center justify-center text-rose-300 hover:text-rose-500 bg-white border border-rose-100 rounded-2xl shadow-sm active:scale-90 transition-all"><span className="material-icons text-xl">delete_outline</span></button>
                    </div>
                  </div>

                  <div className="p-6 md:p-8 space-y-8">
                    {/* Seção de Equipe */}
                    <div className="space-y-4">
                      <div className="flex items-center gap-2 mb-2">
                        <span className="text-[10px] font-black text-slate-300 uppercase tracking-[0.2em]">Equipe de Serviço</span>
                        <div className="flex-1 h-px bg-slate-50"></div>
                      </div>
                      <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 gap-3">
                        <InfoTag label="Portão" value={record.roles.gate} icon="door_sliding" roleId="gate" />

                        {isThursday ? (
                          <InfoTag label="Dirigente" value={record.roles.leader} icon="how_to_reg" roleId="leader" />
                        ) : isWednesday ? (
                          <div className="flex items-center gap-3 p-3 rounded-2xl bg-indigo-50/50 border border-indigo-100/50">
                            <div className="w-9 h-9 rounded-xl flex items-center justify-center shrink-0 bg-white text-indigo-400 border border-indigo-100">
                              <span className="material-icons text-[18px]">stars</span>
                            </div>
                            <div className="flex flex-col">
                              <span className="text-[8px] font-black uppercase tracking-widest text-indigo-400">Grupo</span>
                              <span className="text-[11px] font-black text-indigo-700">Senhoras</span>
                            </div>
                          </div>
                        ) : (
                          <>
                            <InfoTag label="Louvor" value={record.roles.praise} icon="settings_voice" roleId="praise" />
                            <InfoTag label="Palavra" value={record.roles.word} icon="campaign" roleId="word" />
                          </>
                        )}
                      </div>
                    </div>

                    {/* Seção de Mensagem e Hinos */}
                    <div className="space-y-6">
                      <div className="flex items-center gap-2 mb-2">
                        <span className="text-[10px] font-black text-slate-300 uppercase tracking-[0.2em]">Mensagem & Louvores</span>
                        <div className="flex-1 h-px bg-slate-50"></div>
                      </div>

                      <div className="flex flex-col gap-5">
                        {/* Texto Bíblico em destaque */}
                        {!isWednesday && (
                          <div className={`p-5 rounded-3xl border-2 border-dashed flex items-center gap-4 ${
                            record.roles.word === 'TRANSMISSÃO' ? 'bg-amber-50 border-amber-100 text-amber-700' : 'bg-slate-50 border-slate-100 text-slate-600'
                          }`}>
                            <div className="w-11 h-11 rounded-2xl bg-white shadow-sm flex items-center justify-center shrink-0">
                              <span className="material-icons text-xl">{record.roles.word === 'TRANSMISSÃO' ? 'satellite_alt' : 'menu_book'}</span>
                            </div>
                            <div className="flex flex-col min-w-0">
                              <span className="text-[9px] font-black uppercase tracking-[0.15em] opacity-50 mb-0.5">Texto Bíblico</span>
                              <span className="text-sm font-black truncate">
                                {record.roles.word === 'TRANSMISSÃO' ? 'Via Satélite' : (record.roles.scripture || 'NÃO INFORMADO')}
                              </span>
                            </div>
                          </div>
                        )}

                        {/* Lista de Hinos */}
                        {record.songs.length > 0 && (
                          <div className="grid gap-2">
                            {record.songs.map((song, idx) => (
                              <div key={idx} className="flex items-center gap-4 p-4 rounded-2xl bg-slate-50/30 border border-slate-100/50 hover:bg-white hover:shadow-sm transition-all group">
                                <span className="w-6 text-[10px] font-black text-indigo-300 text-center group-hover:text-indigo-500">{idx + 1}</span>
                                <span className="flex-1 text-[11px] font-bold text-slate-600 uppercase tracking-tight">{song}</span>
                                <span className="material-icons text-[14px] text-slate-200">play_circle_outline</span>
                              </div>
                            ))}
                          </div>
                        )}
                      </div>
                    </div>
                  </div>
                </div>
              );
            })}
          </div>
        </div>
      ))}

      {/* Modal de Filtros Avançados */}
      {isFilterModalOpen && (
        <div className="fixed inset-0 z-[8000] flex flex-col justify-end">
          <div className="absolute inset-0 bg-[#1a1c3d]/80 backdrop-blur-sm animate-fadeIn" onClick={() => setIsFilterModalOpen(false)} />
          <div className="relative bg-white rounded-t-[3rem] p-8 max-h-[90vh] flex flex-col shadow-2xl animate-slideUp overflow-hidden">
            <div className="w-12 h-1.5 bg-slate-100 rounded-full mx-auto mb-8 shrink-0"></div>

            <div className="flex justify-between items-center mb-6 shrink-0">
              <h3 className="text-xl font-black text-[#1a1c3d] uppercase tracking-tighter">Filtros Avançados</h3>
              <button onClick={clearAllFilters} className="text-rose-500 font-black text-[9px] uppercase tracking-widest bg-rose-50 px-3 py-1 rounded-full">Limpar Tudo</button>
            </div>

            <div className="flex-1 overflow-y-auto space-y-8 pr-2 custom-scrollbar pb-10">
              {/* Filtro por Tipo */}
              <div className="space-y-3">
                <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest ml-1">Tipo de Culto</label>
                <div className="flex flex-wrap gap-2">
                  {[
                    { id: 'ALL', label: 'Todos' },
                    { id: 'EBD', label: 'EBD' },
                    { id: 'DOM', label: 'Domingo' },
                    { id: 'WEEKDAY', label: 'Semana' }
                  ].map(t => (
                    <button 
                      key={t.id} 
                      onClick={() => setFilterType(t.id as any)}
                      className={`px-5 py-3 rounded-2xl text-[10px] font-black uppercase tracking-widest transition-all ${filterType === t.id ? 'bg-[#1a1c3d] text-white shadow-lg' : 'bg-slate-50 text-slate-400 hover:bg-slate-100'}`}
                    >
                      {t.label}
                    </button>
                  ))}
                </div>
              </div>

              {/* Filtro por Data */}
              <div className="grid grid-cols-2 gap-4">
                <div className="space-y-3">
                  <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest ml-1">Mês</label>
                  <select 
                    value={filterMonth} 
                    onChange={e => setFilterMonth(e.target.value)}
                    className="w-full bg-slate-50 border border-slate-100 rounded-2xl px-4 py-4 font-black text-xs text-[#1a1c3d] outline-none"
                  >
                    <option value="ALL">TODOS</option>
                    {monthNames.map((m, i) => (
                      <option key={m} value={(i + 1).toString().padStart(2, '0')}>{m}</option>
                    ))}
                  </select>
                </div>
                <div className="space-y-3">
                  <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest ml-1">Ano</label>
                  <select 
                    value={filterYear} 
                    onChange={e => setFilterYear(e.target.value)}
                    className="w-full bg-slate-50 border border-slate-100 rounded-2xl px-4 py-4 font-black text-xs text-[#1a1c3d] outline-none"
                  >
                    <option value="ALL">TODOS</option>
                    {years.map(y => <option key={y} value={y}>{y}</option>)}
                  </select>
                </div>
              </div>

              {/* Filtro por Obreiro e Função */}
              <div className="space-y-5 pt-4 border-t border-slate-50">
                <div className="space-y-3">
                  <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest ml-1">Obreiro Específico</label>
                  <select 
                    value={filterWorker} 
                    onChange={e => setFilterWorker(e.target.value)}
                    className="w-full bg-slate-50 border border-slate-100 rounded-2xl px-4 py-4 font-black text-xs text-[#1a1c3d] outline-none"
                  >
                    <option value="ALL">QUALQUER OBREIRO</option>
                    {WORKERS_LIST.map(w => <option key={w} value={w}>{w}</option>)}
                  </select>
                </div>

                <div className="space-y-3">
                  <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest ml-1">Na Função</label>
                  <div className="flex flex-wrap gap-2">
                    {[
                      { id: 'ALL', label: 'Qualquer' },
                      { id: 'gate', label: 'Portão' },
                      { id: 'praise', label: 'Louvor' },
                      { id: 'word', label: 'Palavra' },
                      { id: 'leader', label: 'Dirigente' }
                    ].map(r => (
                      <button 
                        key={r.id} 
                        onClick={() => setFilterRole(r.id)}
                        className={`px-4 py-2.5 rounded-xl text-[9px] font-black uppercase tracking-widest transition-all ${filterRole === r.id ? 'bg-indigo-600 text-white shadow-md' : 'bg-slate-50 text-slate-400 hover:bg-slate-100'}`}
                      >
                        {r.label}
                      </button>
                    ))}
                  </div>
                </div>
              </div>
            </div>

            <div className="p-6 bg-slate-50 border-t border-slate-100 shrink-0">
              <button 
                onClick={() => setIsFilterModalOpen(false)} 
                className="w-full py-5 bg-[#1a1c3d] text-white font-black rounded-3xl uppercase text-[11px] tracking-widest active:scale-95 shadow-xl"
              >
                APLICAR FILTROS
              </button>
            </div>
          </div>
        </div>
      )}

      {itemToDelete && (
        <div className="fixed inset-0 z-[8000] flex flex-col justify-end">
          <div className="absolute inset-0 bg-black/40 backdrop-blur-sm animate-fadeIn" onClick={() => setItemToDelete(null)} />
          <div className="relative bg-white rounded-t-[3rem] p-8 pb-12 shadow-2xl animate-slideUp">
            <div className="w-12 h-1.5 bg-slate-100 rounded-full mx-auto mb-8"></div>
            <div className="flex flex-col items-center text-center">
              <div className="w-16 h-16 bg-rose-50 rounded-full flex items-center justify-center mb-6 text-rose-500">
                <span className="material-icons text-3xl">delete_forever</span>
              </div>
              <h3 className="text-xl font-black text-[#1a1c3d] mb-2 uppercase tracking-tighter">Apagar Registro?</h3>
              <p className="text-slate-400 font-bold text-[10px] uppercase mb-8">Esta ação não pode ser desfeita.</p>
              <div className="w-full flex flex-col gap-3">
                <button onClick={() => { onDelete(itemToDelete!); setItemToDelete(null); }} className="w-full py-5 bg-rose-500 text-white font-black rounded-2xl shadow-xl active:scale-95">EXCLUIR AGORA</button>
                <button onClick={() => setItemToDelete(null)} className="w-full py-4 text-slate-400 font-black uppercase text-[10px] tracking-widest">CANCELAR</button>
              </div>
            </div>
          </div>
        </div>
      )}

      {Object.keys(groupedHistory).length === 0 && (
        <div className="text-center py-24 bg-white/50 rounded-[3rem] border-2 border-dashed border-slate-200 mx-1">
          <span className="material-icons text-slate-200 text-6xl mb-4">history_toggle_off</span>
          <p className="text-slate-400 font-bold text-[10px] uppercase tracking-[0.2em]">Nenhum registro encontrado</p>
          {hasActiveFilters && (
            <button onClick={clearAllFilters} className="mt-4 text-indigo-600 font-black text-[10px] uppercase border-b border-indigo-200">Limpar filtros</button>
          )}
        </div>
      )}
    </div>
  );
};

export default HistoryList;
